import React from 'react';
import { UserCard, StoryPriority } from '../types/process';
import { EditableText } from './EditableText';
import { Button } from './ui/button';
import { Trash2, Plus, User } from 'lucide-react';
import { generateId, cn } from '../lib/utils';

interface UserStoryCardProps {
  card: UserCard;
  onUpdate: (updatedCard: UserCard) => void;
  onDelete: () => void;
}

const PRIORITY_COLORS: Record<StoryPriority, string> = {
  'Essencial': 'bg-red-100 text-red-700 border-red-200',
  'Deveria ter': 'bg-yellow-100 text-yellow-700 border-yellow-200',
  'Poderia ter': 'bg-slate-100 text-slate-700 border-slate-200'
};

export const UserStoryCard: React.FC<UserStoryCardProps> = ({ card, onUpdate, onDelete }) => {

  const addStory = () => {
    if (card.stories.length >= 5) return;
    const newStory = {
      id: generateId(),
      text: '',
      priority: 'Essencial' as StoryPriority
    };
    onUpdate({ ...card, stories: [...card.stories, newStory] });
  };

  const updateStory = (storyId: string, field: 'text' | 'priority', value: string) => {
    const updatedStories = card.stories.map(s => 
      s.id === storyId ? { ...s, [field]: value } : s
    );
    onUpdate({ ...card, stories: updatedStories });
  };

  const removeStory = (storyId: string) => {
    if (confirm('Remover esta história?')) {
      onUpdate({ ...card, stories: card.stories.filter(s => s.id !== storyId) });
    }
  };

  return (
    <div className="bg-slate-50 border border-slate-200 rounded-lg p-4 space-y-4">
      <div className="flex items-center justify-between border-b border-slate-200 pb-2">
        <div className="flex items-center gap-2 flex-1">
          <div className="bg-white p-1.5 rounded-full border border-slate-200 shadow-sm">
            <User className="w-4 h-4 text-slate-500" />
          </div>
          <div className="font-semibold text-sm text-slate-700 flex-1">
             <EditableText 
               value={card.userName} 
               onChange={(val) => onUpdate({ ...card, userName: val })} 
               placeholder="Nome do Usuário/Papel"
             />
          </div>
        </div>
        <Button variant="ghost" size="icon" onClick={onDelete} className="h-6 w-6 text-slate-400 hover:text-red-500">
          <Trash2 className="w-4 h-4" />
        </Button>
      </div>

      <div className="space-y-3">
        {card.stories.map((story) => (
          <div key={story.id} className="flex gap-2 items-start group">
            <div className="flex-1 space-y-1">
               <div className="flex items-center gap-2">
                  <select 
                    className={cn("text-[10px] uppercase font-bold px-1.5 py-0.5 rounded border cursor-pointer outline-none", PRIORITY_COLORS[story.priority])}
                    value={story.priority}
                    onChange={(e) => updateStory(story.id, 'priority', e.target.value)}
                  >
                    <option value="Essencial">Essencial</option>
                    <option value="Deveria ter">Deveria Ter</option>
                    <option value="Poderia ter">Poderia Ter</option>
                  </select>
               </div>
               <EditableText
                 value={story.text}
                 onChange={(val) => updateStory(story.id, 'text', val)}
                 placeholder="Eu quero [ação] para [benefício]..."
                 multiline
                 className="text-sm text-slate-600 bg-white border border-slate-200 rounded p-2"
               />
            </div>
            <button 
              onClick={() => removeStory(story.id)}
              className="opacity-0 group-hover:opacity-100 text-slate-300 hover:text-red-500 transition-opacity mt-6"
            >
              <Trash2 className="w-3 h-3" />
            </button>
          </div>
        ))}
        {card.stories.length < 5 && (
            <Button variant="outline" size="sm" onClick={addStory} className="w-full text-xs border-dashed text-slate-500">
                <Plus className="w-3 h-3 mr-1" /> Adicionar História
            </Button>
        )}
      </div>
    </div>
  );
};

import React from 'react';
import { ProcessStep, UserCard } from '../types/process';
import { EditableText } from './EditableText';
import { UserStoryCard } from './UserStoryCard';
import { Button } from './ui/button';
import { GripVertical, Trash2, Plus, ArrowRight, EyeOff, Eye } from 'lucide-react';
import { generateId, cn } from '../lib/utils';
import { useSortable } from '@dnd-kit/sortable';
import { CSS } from '@dnd-kit/utilities';

interface ProcessStepRowProps {
  step: ProcessStep;
  index: number;
  onUpdate: (updatedStep: ProcessStep) => void;
  onDelete: () => void;
}

export const ProcessStepRow: React.FC<ProcessStepRowProps> = ({ step, index, onUpdate, onDelete }) => {
  const {
    attributes,
    listeners,
    setNodeRef,
    transform,
    transition,
    isDragging
  } = useSortable({ id: step.id });

  const style = {
    transform: CSS.Transform.toString(transform),
    transition,
    zIndex: isDragging ? 10 : 1,
  };

  const addUserCard = () => {
    const newCard: UserCard = {
      id: generateId(),
      userName: '',
      stories: []
    };
    onUpdate({ ...step, userCards: [...step.userCards, newCard] });
  };

  const updateUserCard = (cardIndex: number, updatedCard: UserCard) => {
    const newCards = [...step.userCards];
    newCards[cardIndex] = updatedCard;
    onUpdate({ ...step, userCards: newCards });
  };

  const removeUserCard = (cardIndex: number) => {
     if (confirm('Remover este card de usuário?')) {
        const newCards = step.userCards.filter((_, i) => i !== cardIndex);
        onUpdate({ ...step, userCards: newCards });
     }
  };

  return (
    <div 
      ref={setNodeRef} 
      style={style} 
      className={cn(
        "group relative bg-white border border-slate-200 rounded-xl shadow-sm transition-all mb-4",
        isDragging && "shadow-xl ring-2 ring-blue-500 rotate-1 opacity-90 z-50",
        step.noImprovement && "opacity-75 bg-slate-50/50"
      )}
    >
      {/* Header / Main Row Content */}
      <div className="flex items-stretch p-4 gap-4">
        {/* Drag Handle & Number */}
        <div className="flex flex-col items-center justify-center gap-2 pr-2 border-r border-slate-100">
           <button {...attributes} {...listeners} className="cursor-grab hover:text-blue-600 text-slate-400 active:cursor-grabbing">
             <GripVertical className="w-5 h-5" />
           </button>
           <span className="text-xs font-bold text-slate-400 font-mono">#{index + 1}</span>
        </div>

        {/* Step Content */}
        <div className="flex-1 grid grid-cols-1 md:grid-cols-12 gap-6 items-start">

            {/* Step Name */}
            <div className="md:col-span-3">
                <label className="text-[10px] uppercase font-bold text-slate-400 tracking-wider mb-1 block">Etapa</label>
                <div className="font-semibold text-lg text-slate-800">
                    <EditableText 
                        value={step.name} 
                        onChange={(val) => onUpdate({...step, name: val})}
                        placeholder="Nome da Etapa" 
                    />
                </div>
                <div className="mt-4 flex items-center gap-2">
                    <button 
                        onClick={() => onUpdate({...step, noImprovement: !step.noImprovement})}
                        className={cn(
                            "text-xs flex items-center gap-1.5 px-2 py-1 rounded-full border transition-all",
                            step.noImprovement 
                                ? "bg-slate-200 text-slate-700 border-slate-300" 
                                : "bg-white text-slate-400 border-slate-200 hover:border-slate-300"
                        )}
                    >
                        {step.noImprovement ? <EyeOff className="w-3 h-3" /> : <Eye className="w-3 h-3" />}
                        {step.noImprovement ? "Sem Melhoria" : "Marcar sem melhoria"}
                    </button>
                </div>
            </div>

            {/* As Is */}
            <div className="md:col-span-4 bg-red-50/30 p-3 rounded-lg border border-red-100/50">
                <label className="text-[10px] uppercase font-bold text-red-400 tracking-wider mb-1 block">Como é hoje (AS IS)</label>
                <EditableText 
                    value={step.currentScenario} 
                    onChange={(val) => onUpdate({...step, currentScenario: val})}
                    placeholder="Descreva o processo atual..."
                    multiline
                    className="text-slate-700 leading-relaxed text-sm"
                />
            </div>

            {/* Arrow */}
            <div className="hidden md:flex md:col-span-1 items-center justify-center h-full pt-6 opacity-20">
                <ArrowRight className="w-6 h-6" />
            </div>

            {/* To Be */}
            <div className={cn(
                "md:col-span-4 p-3 rounded-lg border transition-colors",
                step.noImprovement ? "bg-slate-50 border-slate-100" : "bg-green-50/30 border-green-100/50"
            )}>
                <label className={cn(
                    "text-[10px] uppercase font-bold tracking-wider mb-1 block",
                    step.noImprovement ? "text-slate-400" : "text-green-600"
                )}>
                    {step.noImprovement ? "Sem Alteração" : "Como será (TO BE)"}
                </label>
                {!step.noImprovement && (
                    <EditableText 
                        value={step.futureScenario} 
                        onChange={(val) => onUpdate({...step, futureScenario: val})}
                        placeholder="Descreva a melhoria proposta..."
                        multiline
                        className="text-slate-700 leading-relaxed text-sm"
                    />
                )}
                {step.noImprovement && (
                    <p className="text-sm text-slate-400 italic py-2">Esta etapa não sofrerá alterações.</p>
                )}
            </div>

        </div>

        {/* Delete Button */}
        <div className="flex items-start pl-2">
            <Button variant="ghost" size="icon" onClick={onDelete} className="text-slate-300 hover:text-red-500 hover:bg-red-50">
                <Trash2 className="w-4 h-4" />
            </Button>
        </div>
      </div>

      {/* User Stories Section */}
      {!step.noImprovement && (
        <div className="border-t border-slate-100 bg-slate-50/50 p-4 rounded-b-xl">
            <div className="flex items-center justify-between mb-4">
                <h4 className="text-sm font-semibold text-slate-600 flex items-center gap-2">
                    <UserCardIcon className="w-4 h-4" />
                    Histórias de Usuário
                    <span className="text-xs font-normal text-slate-400 bg-slate-200 px-1.5 rounded-full">{step.userCards.length}</span>
                </h4>
                <Button variant="outline" size="sm" onClick={addUserCard} className="bg-white hover:bg-slate-50 text-xs h-7">
                    <Plus className="w-3 h-3 mr-1" /> Novo Card
                </Button>
            </div>

            {step.userCards.length > 0 ? (
                <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
                    {step.userCards.map((card, idx) => (
                        <UserStoryCard 
                            key={card.id}
                            card={card}
                            onUpdate={(updated) => updateUserCard(idx, updated)}
                            onDelete={() => removeUserCard(idx)}
                        />
                    ))}
                </div>
            ) : (
                <div className="text-center py-4 text-slate-400 text-sm italic border border-dashed border-slate-200 rounded-lg">
                    Nenhuma história de usuário vinculada a esta etapa.
                </div>
            )}
        </div>
      )}
    </div>
  );
};

