        step.noImprovement ? 'Sim' : 'Não'
    ]);
    const wsSteps = XLSX.utils.aoa_to_sheet([stepsHeader, ...stepsData]);
    XLSX.utils.book_append_sheet(wb, wsSteps, "Etapas");

    // Sheet 3: User Stories Flattened
    const storiesHeader = ['Etapa', 'Usuário', 'Prioridade', 'História'];
    const storiesData: any[] = [];
    data.steps.forEach(step => {
        step.userCards.forEach(card => {
            card.stories.forEach(story => {
                storiesData.push([
                    step.name,
                    card.userName,
                    story.priority,
                    story.text
                ]);
            });
        });
    });
    const wsStories = XLSX.utils.aoa_to_sheet([storiesHeader, ...storiesData]);
    XLSX.utils.book_append_sheet(wb, wsStories, "Histórias");

    XLSX.writeFile(wb, `${data.title || 'processo'}.xlsx`);
};

export const exportToPDF = (data: ProcessImprovement) => {
    const doc = new jsPDF();

    // Header
    doc.setFontSize(18);
    doc.text(data.title || 'Sem Título', 14, 22);

    doc.setFontSize(11);
    doc.setTextColor(100);
    doc.text(`Tema: ${data.theme}`, 14, 30);
    doc.text(`Setores: ${data.sectors}`, 14, 36);
    doc.text(`Gestores: ${data.managers}`, 14, 42);

    // Table
    const tableRows = data.steps.map((step, i) => [
        (i + 1).toString(),
        step.name,
        step.currentScenario,
        step.noImprovement ? 'N/A' : step.futureScenario,
        step.userCards.length.toString()
    ]);

    autoTable(doc, {
        head: [['#', 'Etapa', 'Como é hoje', 'Como será', 'Cards']],
        body: tableRows,
        startY: 50,
        styles: { fontSize: 8 },
        headStyles: { fillColor: [41, 128, 185] }
    });

    doc.save(`${data.title || 'processo'}.pdf`);
};

import React, { useState } from 'react';
import { ProcessImprovement, ProcessStep } from '../types/process';
import { ProcessStepRow } from './ProcessStepRow';
import { Button } from './ui/button';
import { Plus, Eye, EyeOff } from 'lucide-react';
import { generateId } from '../lib/utils';
import {
  DndContext, 
  closestCenter,
  KeyboardSensor,
  PointerSensor,
  useSensor,
  useSensors,
  DragEndEvent
} from '@dnd-kit/core';
import {
  arrayMove,
  SortableContext,
  sortableKeyboardCoordinates,
  verticalListSortingStrategy,
} from '@dnd-kit/sortable';

interface ProcessTableProps {
  data: ProcessImprovement;
  onUpdate: (newData: ProcessImprovement) => void;
}

export const ProcessTable: React.FC<ProcessTableProps> = ({ data, onUpdate }) => {
  const [showNoImprovement, setShowNoImprovement] = useState(true);

  const sensors = useSensors(
    useSensor(PointerSensor),
    useSensor(KeyboardSensor, {
      coordinateGetter: sortableKeyboardCoordinates,
    })
  );

  const handleDragEnd = (event: DragEndEvent) => {
    const { active, over } = event;

    if (over && active.id !== over.id) {
      const oldIndex = data.steps.findIndex((step) => step.id === active.id);
      const newIndex = data.steps.findIndex((step) => step.id === over.id);

      const newSteps = arrayMove(data.steps, oldIndex, newIndex);
      onUpdate({ ...data, steps: newSteps });
    }
  };

  const addStep = () => {
    const newStep: ProcessStep = {
      id: generateId(),
      name: '',
      currentScenario: '',
      futureScenario: '',
      noImprovement: false,
      userCards: []
    };
    onUpdate({ ...data, steps: [...data.steps, newStep] });
  };

  const updateStep = (index: number, updatedStep: ProcessStep) => {
    const newSteps = [...data.steps];
    newSteps[index] = updatedStep;
    onUpdate({ ...data, steps: newSteps });
  };

  const deleteStep = (index: number) => {
    if (confirm('Tem certeza que deseja excluir esta etapa e todas as suas histórias?')) {
      const newSteps = data.steps.filter((_, i) => i !== index);
      onUpdate({ ...data, steps: newSteps });
    }
  };

  const visibleSteps = showNoImprovement 
    ? data.steps 
    : data.steps.filter(s => !s.noImprovement);

  return (
    <div className="space-y-4">
      <div className="flex items-center justify-between">
        <h2 className="text-xl font-bold text-slate-800">Fluxo do Processo</h2>
        <div className="flex items-center gap-4">
             <button 
                onClick={() => setShowNoImprovement(!showNoImprovement)}
                className="text-sm text-slate-500 hover:text-blue-600 flex items-center gap-2"
             >
                {showNoImprovement ? <Eye className="w-4 h-4" /> : <EyeOff className="w-4 h-4" />}
                {showNoImprovement ? "Ocultar 'Sem Melhoria'" : "Mostrar 'Sem Melhoria'"}
             </button>
        </div>
      </div>

      <DndContext 
        sensors={sensors}
        collisionDetection={closestCenter}
        onDragEnd={handleDragEnd}
      >
        <SortableContext 
          items={visibleSteps.map(s => s.id)}
          strategy={verticalListSortingStrategy}
        >
          <div className="space-y-4">
            {visibleSteps.map((step, index) => {
                // Find true index in original array for updates
                const realIndex = data.steps.findIndex(s => s.id === step.id);
                return (
                    <ProcessStepRow 
                        key={step.id} 
                        step={step} 
                        index={realIndex}
                        onUpdate={(updated) => updateStep(realIndex, updated)}
                        onDelete={() => deleteStep(realIndex)}
                    />
                )
            })}
          </div>
        </SortableContext>
      </DndContext>

      <Button 
        onClick={addStep} 
        variant="outline" 
        className="w-full border-dashed border-2 py-8 text-slate-500 hover:text-blue-600 hover:border-blue-200 hover:bg-blue-50"
      >
        <Plus className="w-5 h-5 mr-2" />
        Adicionar Nova Etapa ao Processo
      </Button>
    </div>
  );
};

