import React, { useState, useEffect } from 'react';
import { ProcessHeader } from './components/ProcessHeader';
import { ProcessTable } from './components/ProcessTable';
import { ExportButtons } from './components/ExportButtons';
import { ProcessImprovement } from './types/process';
import { loadFromLocalStorage, saveToLocalStorage } from './utils/exportUtils';

function App() {
  const [data, setData] = useState<ProcessImprovement | null>(null);

  useEffect(() => {
    const loadedData = loadFromLocalStorage();
    setData(loadedData);
  }, []);

  useEffect(() => {
    if (data) {
      const timeoutId = setTimeout(() => {
        saveToLocalStorage(data);
      }, 1000);
      return () => clearTimeout(timeoutId);
    }
  }, [data]);

  const handleUpdate = (field: keyof ProcessImprovement, value: any) => {
    if (!data) return;
    setData({ ...data, [field]: value });
  };

  const handleFullUpdate = (newData: ProcessImprovement) => {
    setData(newData);
  };

  const handleImport = (e: React.ChangeEvent<HTMLInputElement>) => {
      const file = e.target.files?.[0];
      if (file) {
          const reader = new FileReader();
          reader.onload = (event) => {
              try {
                  const importedData = JSON.parse(event.target?.result as string);
                  if (importedData.steps) { // Basic validation
                      setData(importedData);
                      alert('Processo importado com sucesso!');
                  }
              } catch (error) {
                  alert('Erro ao importar arquivo.');
              }
          };
          reader.readAsText(file);
      }
  };

  if (!data) return <div className="flex items-center justify-center h-screen">Carregando...</div>;

  return (
    <div className="min-h-screen bg-slate-50/50 pb-24 font-sans text-slate-900">
      <div className="max-w-6xl mx-auto p-6">
        <div className="mb-8 flex items-center justify-between">
             <div className="text-sm text-slate-400 font-medium">
                Última sincronização: {new Date().toLocaleTimeString()}
             </div>
        </div>

        <ProcessHeader 
          data={data} 
          onUpdate={handleUpdate} 
        />

        <ProcessTable 
          data={data} 
          onUpdate={handleFullUpdate} 
        />

        <ExportButtons data={data} onImport={handleImport} />
      </div>
    </div>
  );
}

export default App;

