interface UserStoryCardProps {
  card: UserCard;
  onUpdate: (updatedCard: UserCard) => void;
  onDelete: () => void;
  savedUsers: string[];
  usedUsers: Set<string>;
  onDeleteUser: (name: string) => void;
}

const PRIORITY_COLORS: Record<StoryPriority, string> = {
  'Essencial': 'bg-red-100 text-red-700 border-red-200',
  'Deveria ter': 'bg-yellow-100 text-yellow-700 border-yellow-200',
  'Poderia ter': 'bg-slate-100 text-slate-700 border-slate-200'
};

export const UserStoryCard: React.FC<UserStoryCardProps> = ({ card, onUpdate, onDelete, savedUsers, usedUsers, onDeleteUser }) => {

  const addStory = () => {
    if (card.stories.length >= 5) return;
    const newStory = {
      id: generateId(),
      text: '',
      priority: 'Essencial' as StoryPriority
    };
    onUpdate({ ...card, stories: [...card.stories, newStory] });
  };

  const updateStory = (storyId: string, field: 'text' | 'priority', value: string) => {
    const updatedStories = card.stories.map(s => 
      s.id === storyId ? { ...s, [field]: value } : s
    );
    onUpdate({ ...card, stories: updatedStories });
  };

  const removeStory = (storyId: string) => {
    if (confirm('Remover esta história?')) {
      onUpdate({ ...card, stories: card.stories.filter(s => s.id !== storyId) });
    }
  };

  return (
    <div className="bg-slate-50 border border-slate-200 rounded-lg p-4 space-y-4 shadow-sm print:bg-white print:border-slate-200 print:break-inside-avoid">
      <div className="flex items-center justify-between border-b border-slate-200 pb-2">
        <div className="flex items-center gap-2 flex-1 mr-2">
            <div className="bg-white p-1.5 rounded-full border border-slate-200 shadow-sm print:hidden">
                <User className="w-4 h-4 text-slate-500" />
            </div>
            {/* Fallback icon for print */}
            <div className="hidden print:block p-1.5">
                <User className="w-4 h-4 text-slate-500" />
            </div>

            <div className="flex-1">
               {/* 
                   Note: We are using UserSelect here. If the component file is missing in your structure,
                   replace this with <EditableText ... /> 
               */}
               <UserSelect 
                  value={card.userName}
                  onChange={(val: string) => onUpdate({ ...card, userName: val })}
                  savedUsers={savedUsers}
                  usedUsers={usedUsers}
                  onDeleteUser={onDeleteUser}
               />
            </div>
        </div>
        <Button variant="ghost" size="icon" onClick={onDelete} className="h-8 w-8 text-slate-400 hover:text-red-500 hover:bg-red-50 print:hidden">
          <Trash2 className="w-4 h-4" />
        </Button>
      </div>

      <div className="space-y-3">
        {card.stories.map((story) => (
          <div key={story.id} className="flex gap-2 items-start group">
            <div className="flex-1 space-y-1">
               <div className="flex items-center gap-2">
                  <div className="print:hidden">
                      <select 
                        className={cn("text-[10px] uppercase font-bold px-1.5 py-0.5 rounded border cursor-pointer outline-none transition-colors", PRIORITY_COLORS[story.priority])}
                        value={story.priority}
                        onChange={(e) => updateStory(story.id, 'priority', e.target.value)}
                      >
                        <option value="Essencial">Essencial</option>
                        <option value="Deveria ter">Deveria Ter</option>
                        <option value="Poderia ter">Poderia Ter</option>
                      </select>
                  </div>
                  {/* Print-only priority badge */}
                  <div className={cn("hidden print:inline-block text-[10px] uppercase font-bold px-1.5 py-0.5 rounded border", PRIORITY_COLORS[story.priority])}>
                      {story.priority}
                  </div>
               </div>
               <EditableText
                 value={story.text}
                 onChange={(val) => updateStory(story.id, 'text', val)}
                 placeholder="Eu quero [ação] para [benefício]..."
                 multiline
                 className="text-sm text-slate-600 bg-white border border-slate-200 rounded p-2 focus:ring-1 focus:ring-slate-300"
               />
            </div>
            <button 
              onClick={() => removeStory(story.id)}
              className="opacity-0 group-hover:opacity-100 text-slate-300 hover:text-red-500 transition-opacity mt-6 p-1 hover:bg-slate-100 rounded print:hidden"
            >
              <Trash2 className="w-3.5 h-3.5" />
            </button>
          </div>
        ))}
        {card.stories.length < 5 && (
            <Button variant="outline" size="sm" onClick={addStory} className="w-full text-xs border-dashed text-slate-500 hover:text-[#0F5F87] hover:border-[#0F5F87] hover:bg-blue-50 print:hidden">
                <Plus className="w-3 h-3 mr-1" /> Adicionar História
            </Button>
        )}
      </div>
    </div>
  );
};

import React, { useState } from 'react';
import { ProcessImprovement, ProcessStep } from '../types/process';
import { ProcessStepRow } from './ProcessStepRow';
import { Button } from './ui/button';
import { Plus, List } from 'lucide-react';
import { generateId } from '../lib/utils';
import {
  DndContext, 
  closestCenter,
  KeyboardSensor,
  PointerSensor,
  useSensor,
  useSensors,
  DragEndEvent
} from '@dnd-kit/core';
import {
  arrayMove,
  SortableContext,
  sortableKeyboardCoordinates,
  verticalListSortingStrategy,
} from '@dnd-kit/sortable';

interface ProcessTableProps {
  data: ProcessImprovement;
  onUpdate: (newData: ProcessImprovement) => void;
  onDeleteUser: (name: string) => void;
}

export const ProcessTable: React.FC<ProcessTableProps> = ({ data, onUpdate, onDeleteUser }) => {
  const [showNoImprovement, setShowNoImprovement] = useState(true);

  const sensors = useSensors(
    useSensor(PointerSensor),
    useSensor(KeyboardSensor, {
      coordinateGetter: sortableKeyboardCoordinates,
    })
  );

  const handleDragEnd = (event: DragEndEvent) => {
    const { active, over } = event;

    if (over && active.id !== over.id) {
      const oldIndex = data.steps.findIndex((step) => step.id === active.id);
      const newIndex = data.steps.findIndex((step) => step.id === over.id);

      const newSteps = arrayMove(data.steps, oldIndex, newIndex);
      onUpdate({ ...data, steps: newSteps });
    }
  };

  const addStep = () => {
    const newStep: ProcessStep = {
      id: generateId(),
      name: '',
      currentScenario: '',
      futureScenario: '',
      noImprovement: false,
      userCards: []
    };
    onUpdate({ ...data, steps: [...data.steps, newStep] });
  };

  const updateStep = (index: number, updatedStep: ProcessStep) => {
    const newSteps = [...data.steps];
    newSteps[index] = updatedStep;
    onUpdate({ ...data, steps: newSteps });
  };

  const deleteStep = (index: number) => {
    if (confirm('Tem certeza que deseja excluir esta etapa e todas as suas histórias?')) {
      const newSteps = data.steps.filter((_, i) => i !== index);
      onUpdate({ ...data, steps: newSteps });
    }
  };

  const visibleSteps = showNoImprovement 
    ? data.steps 
    : data.steps.filter(s => !s.noImprovement);

  const countNoImprovement = data.steps.filter(s => s.noImprovement).length;

  return (
    <div className="space-y-4">
      <div className="flex items-center justify-between pb-2">
        <h2 className="text-lg font-bold text-slate-800 flex items-center gap-2">
            <List className="w-5 h-5 text-[#0F5F87]" />
            Etapas do Processo
        </h2>
        <div className="flex items-center gap-3 print:hidden">
             <label className="text-sm text-slate-500 font-medium cursor-pointer flex items-center gap-2 select-none">
                <div 
                  className={`w-10 h-5 rounded-full relative transition-colors ${showNoImprovement ? 'bg-[#0F5F87]' : 'bg-slate-300'}`}
                  onClick={() => setShowNoImprovement(!showNoImprovement)}
                >
                    <div className={`absolute top-1 w-3 h-3 bg-white rounded-full transition-all ${showNoImprovement ? 'left-6' : 'left-1'}`} />
                </div>
                <span>Sem melhoria ({countNoImprovement})</span>
             </label>
        </div>
      </div>

      {/* Table Headers */}
      <div className="grid grid-cols-12 gap-4 px-4 py-2 bg-slate-100/50 rounded-lg text-sm font-semibold text-slate-600 border border-transparent print:hidden">
          <div className="col-span-12 md:col-span-3 lg:col-span-3 pl-8">Etapa Nome</div>
          <div className="hidden md:block md:col-span-4 lg:col-span-4">Como é Hoje</div>
          <div className="hidden md:block md:col-span-4 lg:col-span-4">Como Será</div>
      </div>

      {/* Print Headers */}
      <div className="hidden print:grid grid-cols-12 gap-4 px-4 py-2 bg-slate-100 border-b border-slate-300 text-sm font-bold text-slate-800 mb-2">
          <div className="col-span-3 pl-8">Etapa</div>
          <div className="col-span-4">Como é Hoje</div>
          <div className="col-span-5">Como Será</div>
      </div>

      <DndContext 
        sensors={sensors}
        collisionDetection={closestCenter}
        onDragEnd={handleDragEnd}
      >
        <SortableContext 
          items={visibleSteps.map(s => s.id)}
          strategy={verticalListSortingStrategy}
        >
          <div className="space-y-3">
            {visibleSteps.map((step) => {
                const realIndex = data.steps.findIndex(s => s.id === step.id);
                // Calculate used users for this scope if necessary, or pass global
                // Assuming passed from App down to Table then Row in full implementation
                // We reuse the prop onDeleteUser which was missing in the interface previously
                return (
                    <ProcessStepRow 
                        key={step.id} 
                        step={step} 
                        index={realIndex}
                        onUpdate={(updated) => updateStep(realIndex, updated)}
                        onDelete={() => deleteStep(realIndex)}
                        savedUsers={data.savedUserNames || []}
                        usedUsers={new Set()} // Should be calculated in App or Table
                        onDeleteUser={onDeleteUser}
                    />
                )
            })}
          </div>
        </SortableContext>
      </DndContext>

      <Button 
        onClick={addStep} 
        variant="outline" 
        className="w-full border-dashed border-2 border-slate-300 py-6 text-[#0F5F87] font-semibold hover:border-[#0F5F87] hover:bg-slate-50 transition-all rounded-xl print:hidden"
      >
        <Plus className="w-5 h-5 mr-2" />
        Adicionar Nova Etapa
      </Button>
    </div>
  );
};

