import React, { useState, useEffect, useRef } from 'react';
import { User, ChevronDown, Trash2 } from 'lucide-react';
import { cn } from '../lib/utils';

interface UserSelectProps {
    value: string;
    onChange: (value: string) => void;
    savedUsers: string[];
    usedUsers: Set<string>;
    onDeleteUser: (user: string) => void;
}

export const UserSelect: React.FC<UserSelectProps> = ({ value, onChange, savedUsers, usedUsers, onDeleteUser }) => {
    const [isOpen, setIsOpen] = useState(false);
    const [localValue, setLocalValue] = useState(value);
    const [searchTerm, setSearchTerm] = useState("");
    const wrapperRef = useRef<HTMLDivElement>(null);

    // Sync local value when prop changes (external updates)
    useEffect(() => {
        setLocalValue(value);
    }, [value]);

    useEffect(() => {
        const handleClickOutside = (event: MouseEvent) => {
            if (wrapperRef.current && !wrapperRef.current.contains(event.target as Node)) {
                setIsOpen(false);
            }
        };
        document.addEventListener("mousedown", handleClickOutside);
        return () => document.removeEventListener("mousedown", handleClickOutside);
    }, []);

    const filteredUsers = savedUsers
        .filter(u => u.toLowerCase().includes(searchTerm.toLowerCase()))
        .sort();

    const handleSelect = (user: string) => {
        setLocalValue(user);
        onChange(user);
        setIsOpen(false);
        setSearchTerm("");
    };

    const handleCommit = () => {
         if (localValue !== value) {
             onChange(localValue);
         }
    };

    return (
        <div className="relative w-full" ref={wrapperRef}>
            <div 
                className={cn(
                    "flex items-center border border-slate-200 bg-white rounded-md focus-within:ring-2 focus-within:ring-slate-950 focus-within:ring-offset-2 transition-all print:border-none print:bg-transparent print:p-0",
                    isOpen && "ring-2 ring-slate-950 ring-offset-2"
                )}
            >
                <div className="pl-2 print:hidden">
                    <User className="w-4 h-4 text-slate-400" />
                </div>
                <input
                    type="text"
                    className="flex-1 border-none focus:ring-0 text-sm py-1.5 px-2 bg-transparent outline-none placeholder:text-slate-400 print:px-0"
                    value={localValue}
                    onChange={(e) => {
                        setLocalValue(e.target.value);
                        setSearchTerm(e.target.value);
                    }}
                    onFocus={() => setIsOpen(true)}
                    onBlur={handleCommit}
                    onKeyDown={(e) => {
                         if (e.key === 'Enter') {
                             e.preventDefault();
                             handleCommit();
                             setIsOpen(false);
                         }
                    }}
                    placeholder="Selecione ou digite..."
                />
                <button 
                    className="px-2 text-slate-400 hover:text-slate-600 focus:outline-none print:hidden"
                    onClick={() => setIsOpen(!isOpen)}
                >
                    <ChevronDown className="w-4 h-4" />
                </button>
            </div>

            {isOpen && (
                <div className="absolute top-full left-0 w-full mt-1 bg-white border border-slate-200 rounded-md shadow-lg z-50 max-h-48 overflow-auto animate-in fade-in zoom-in-95 duration-100 print:hidden">
                    {filteredUsers.length > 0 ? (
                        <ul className="py-1">
                            {filteredUsers.map((user) => {
                                const isUsed = usedUsers.has(user);
                                return (
                                    <li 
                                        key={user} 
                                        className="flex items-center justify-between px-3 py-2 hover:bg-slate-100 text-sm text-slate-700 group cursor-pointer"
                                        onMouseDown={(e) => {
                                            e.preventDefault(); 
                                            handleSelect(user);
                                        }}
                                    >
                                        <span className="truncate flex-1">{user}</span>
                                        {!isUsed ? (
                                            <button 
                                                onMouseDown={(e) => {
                                                    e.stopPropagation();
                                                    onDeleteUser(user);
                                                }}
                                                className="p-1 text-slate-300 hover:text-red-500 hover:bg-red-50 rounded transition-colors"
                                                title="Excluir usuário (não utilizado)"
                                            >
                                                <Trash2 className="w-3.5 h-3.5" />
                                            </button>
                                        ) : (
                                            <span className="text-[10px] text-slate-400 bg-slate-50 px-1.5 py-0.5 rounded border border-slate-100">
                                                Em uso
                                            </span>
                                        )}
                                    </li>
                                );
                            })}
                        </ul>
                    ) : (
                        <div className="px-3 py-2 text-sm text-slate-400 italic">
                            {searchTerm ? "Nenhum usuário encontrado" : "Nenhum usuário salvo"}
                        </div>
                    )}
                </div>
            )}
        </div>
    );
};

