import React, { useState, useEffect } from 'react';
import { Sidebar } from './components/Sidebar';
import { ProcessHeader } from './components/ProcessHeader';
import { ProcessTable } from './components/ProcessTable';
import { ExportButtons } from './components/ExportButtons';
import { ProcessImprovement } from './types/process';
import { loadAllProcesses, saveProcess, saveProcessManager, getEmptyProcess } from './utils/exportUtils';

interface ProcessManager {
    processesInfo: { id: string, title: string }[];
    activeProcessId: string | null;
}

export function App() {
  const [processes, setProcesses] = useState<ProcessImprovement[]>([]);
  const [activeProcessId, setActiveProcessId] = useState<string | null>(null);
  const [isSidebarVisible, setIsSidebarVisible] = useState(true);

  useEffect(() => {
    const { processes: loadedProcesses, activeProcessId: loadedActiveId } = loadAllProcesses();
    setProcesses(loadedProcesses);
    setActiveProcessId(loadedActiveId);
  }, []);

  const activeProcess = processes.find(p => p.id === activeProcessId) || null;

  // Auto-save manager and active process
  useEffect(() => {
    if (activeProcess) {
      // Auto-sync users for the active process
      const currentUsers = new Set(activeProcess.savedUserNames || []);
      let hasUserChanges = false;
      activeProcess.steps.forEach(step => {
        step.userCards.forEach(card => {
          const name = card.userName?.trim();
          if (name && !currentUsers.has(name)) {
            currentUsers.add(name);
            hasUserChanges = true;
          }
        });
      });

      if (hasUserChanges) {
        handleFullUpdate({ ...activeProcess, savedUserNames: Array.from(currentUsers) });
      } else {
        const timeoutId = setTimeout(() => {
          saveProcess(activeProcess);
          saveProcessManager({
            processesInfo: processes.map(p => ({ id: p.id, title: p.title || "Processo sem título" })),
            activeProcessId,
          });
        }, 1000);
        return () => clearTimeout(timeoutId);
      }
    }
  }, [processes, activeProcessId]);


  const handleUpdate = (field: keyof ProcessImprovement, value: any) => {
    if (!activeProcess) return;
    const updatedProcess = { ...activeProcess, [field]: value };
    const newProcesses = processes.map(p => p.id === activeProcessId ? updatedProcess : p);
    setProcesses(newProcesses);
  };

  const handleFullUpdate = (newData: ProcessImprovement) => {
    const newProcesses = processes.map(p => p.id === activeProcessId ? newData : p);
    setProcesses(newProcesses);
  };

  const handleDeleteUser = (userToDelete: string) => {
    if (!activeProcess) return;
    const newSavedUsers = (activeProcess.savedUserNames || []).filter(u => u !== userToDelete);
    handleUpdate('savedUserNames', newSavedUsers);
  };

  const handleSelectProcess = (id: string) => {
      setActiveProcessId(id);
  };

  const handleCreateProcess = () => {
      const newProcess = getEmptyProcess();
      newProcess.title = `Novo Processo ${processes.length + 1}`;
      setProcesses([...processes, newProcess]);
      setActiveProcessId(newProcess.id);
  };

  const handleDeleteProcess = (idToDelete: string) => {
      if (processes.length <= 1) {
          alert("Não é possível excluir o único processo existente.");
          return;
      }
      if (confirm("Tem certeza que deseja excluir este processo? Esta ação não pode ser desfeita.")) {
          const newProcesses = processes.filter(p => p.id !== idToDelete);
          setProcesses(newProcesses);
          if (activeProcessId === idToDelete) {
              setActiveProcessId(newProcesses[0]?.id || null);
          }
      }
  };

  const handleRenameProcess = (idToRename: string, newTitle: string) => {
       const newProcesses = processes.map(p => 
           p.id === idToRename ? { ...p, title: newTitle } : p
       );
       setProcesses(newProcesses);
  };

  const handleImport = (e: React.ChangeEvent<HTMLInputElement>) => {
      const file = e.target.files?.[0];
      if (file) {
          const reader = new FileReader();
          reader.onload = (event) => {
              try {
                  const importedData = JSON.parse(event.target?.result as string) as ProcessImprovement;
                  if (importedData.steps && importedData.id) {
                      if (!importedData.savedUserNames) importedData.savedUserNames = [];
                      setProcesses([...processes, importedData]);
                      setActiveProcessId(importedData.id);
                      alert('Processo importado com sucesso!');
                  }
              } catch (error) {
                  alert('Erro ao importar arquivo. Certifique-se que é um JSON válido exportado pela ferramenta.');
              }
          };
          reader.readAsText(file);
      }
  };

  if (!activeProcess) return <div className="flex items-center justify-center h-screen text-slate-500">Carregando processos...</div>;

  return (
    <div className="flex min-h-screen bg-slate-100">
      <Sidebar 
        processes={processes}
        activeProcessId={activeProcessId}
        onSelect={handleSelectProcess}
        onCreate={handleCreateProcess}
        onDelete={handleDeleteProcess}
        onRename={handleRenameProcess}
        isVisible={isSidebarVisible}
        onToggle={() => setIsSidebarVisible(!isSidebarVisible)}
      />
      <main className={`flex-1 transition-all duration-300 ${isSidebarVisible ? 'md:ml-64' : 'ml-0'}`}>
        <div className="min-h-screen bg-slate-50 pb-24 font-sans text-slate-900">
            <div className="max-w-[1400px] mx-auto p-6 space-y-6">

                <div className="flex items-center justify-between">
                   <div className="text-sm text-slate-500">
                      Processo Ativo: <span className="font-semibold text-slate-700">{activeProcess.title}</span>
                   </div>
                   <ExportButtons activeProcess={activeProcess} onImport={handleImport} />
                </div>

                <ProcessHeader 
                data={activeProcess} 
                onUpdate={handleUpdate} 
                />

                <ProcessTable 
                data={activeProcess} 
                onUpdate={handleFullUpdate} 
                onDeleteUser={handleDeleteUser}
                />

                <div className="text-center text-xs text-slate-400 mt-8 print:hidden">
                💡 Clique em qualquer texto para editar. Clique nas linhas para expandir e adicionar histórias de usuário.
                </div>
            </div>
        </div>
      </main>
    </div>
  );
}

