import { ProcessImprovement } from "../types/process";
import { generateId } from "../lib/utils";
import * as XLSX from 'xlsx';

const MANAGER_KEY = 'process_manager_v1';
const getProcessKey = (id: string) => `process_data_${id}`;

interface ProcessManager {
    processesInfo: { id: string, title: string }[];
    activeProcessId: string | null;
}

export const getEmptyProcess = (): ProcessImprovement => ({
    id: generateId(),
    title: 'Processo sem título',
    theme: '',
    sectors: '',
    managers: '',
    steps: [],
    updatedAt: new Date().toISOString(),
    savedUserNames: []
});

export const saveProcess = (processData: ProcessImprovement) => {
    try {
        localStorage.setItem(getProcessKey(processData.id), JSON.stringify(processData));
    } catch (e) {
        console.error(`Failed to save process ${processData.id}`, e);
    }
};

export const saveProcessManager = (managerData: ProcessManager) => {
    try {
        localStorage.setItem(MANAGER_KEY, JSON.stringify(managerData));
    } catch (e) {
        console.error('Failed to save process manager', e);
    }
};

export const loadAllProcesses = (): { processes: ProcessImprovement[], activeProcessId: string | null } => {
    try {
        const managerDataJSON = localStorage.getItem(MANAGER_KEY);
        if (managerDataJSON) {
            const managerData: ProcessManager = JSON.parse(managerDataJSON);
            const processes = managerData.processesInfo.map(info => {
                try {
                    const processJSON = localStorage.getItem(getProcessKey(info.id));
                    return processJSON ? JSON.parse(processJSON) : null;
                } catch {
                    return null;
                }
            }).filter(Boolean) as ProcessImprovement[];

            // Se algum processo não pôde ser carregado, limpamos a lista
            if(processes.length !== managerData.processesInfo.length) {
                console.warn("Alguns processos não puderam ser carregados. Verificando...");
                const validProcesses = processes;
                const validManagerData: ProcessManager = {
                    processesInfo: validProcesses.map(p => ({ id: p.id, title: p.title })),
                    activeProcessId: validProcesses.find(p => p.id === managerData.activeProcessId) ? managerData.activeProcessId : (validProcesses[0]?.id || null)
                };
                saveProcessManager(validManagerData);
                return { processes: validProcesses, activeProcessId: validManagerData.activeProcessId };
            }

            return { processes, activeProcessId: managerData.activeProcessId };
        }
    } catch (e) {
        console.error('Failed to load process manager', e);
    }

    // Se não houver nada, cria o primeiro processo
    const firstProcess = getEmptyProcess();
    firstProcess.title = "Meu Primeiro Processo";
    const managerData: ProcessManager = {
        processesInfo: [{ id: firstProcess.id, title: firstProcess.title }],
        activeProcessId: firstProcess.id
    };
    saveProcess(firstProcess);
    saveProcessManager(managerData);

    return { processes: [firstProcess], activeProcessId: firstProcess.id };
};


export const exportToCSV = (data: ProcessImprovement) => {
    const headers = ['Etapa #', 'Nome', 'Como é hoje', 'Como será', 'Sem Melhoria', 'Usuário', 'Prioridade', 'História'];
    const rows: string[][] = [];

    data.steps.forEach((step, index) => {
        const baseRow = [
            (index + 1).toString(),
            step.name,
            step.currentScenario,
            step.noImprovement ? 'Sim' : 'Não',
            step.noImprovement ? 'N/A' : step.futureScenario
        ];

        if (step.userCards.length === 0) {
            rows.push([...baseRow, '', '', '']);
        } else {
            step.userCards.forEach(card => {
                if (card.stories.length === 0) {
                    rows.push([...baseRow, card.userName, '', '']);
                } else {
                    card.stories.forEach(story => {
                        rows.push([
                            ...baseRow,
                            card.userName,
                            story.priority,
                            story.text
                        ]);
                    });
                }
            });
        }
    });

    let csvContent = "data:text/csv;charset=utf-8," 
        + headers.join(",") + "\n" 
        + rows.map(e => e.map(cell => `"${(cell || '').replace(/"/g, '""')}"`).join(",")).join("\n");

    const encodedUri = encodeURI(csvContent);
    const link = document.createElement("a");
    link.setAttribute("href", encodedUri);
    link.setAttribute("download", `${data.title || 'processo'}.csv`);
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
};

export const exportToXLSX = (data: ProcessImprovement) => {
    const wb = XLSX.utils.book_new();

    // Sheet 1: Info
    const infoData = [
        ['Título', data.title],
        ['Tema', data.theme],
        ['Setores', data.sectors],
        ['Gestores', data.managers],
        ['Data', new Date().toLocaleDateString()]
    ];
    const wsInfo = XLSX.utils.aoa_to_sheet(infoData);
    XLSX.utils.book_append_sheet(wb, wsInfo, "Informações");

    // Sheet 2: Steps
    const stepsHeader = ['#', 'Nome', 'Como é hoje', 'Como será', 'Sem Melhoria'];
    const stepsData = data.steps.map((step, i) => [
        i + 1,
        step.name,
        step.currentScenario,
        step.futureScenario,
        step.noImprovement ? 'Sim' : 'Não'
    ]);
    const wsSteps = XLSX.utils.aoa_to_sheet([stepsHeader, ...stepsData]);
    XLSX.utils.book_append_sheet(wb, wsSteps, "Etapas");

    // Sheet 3: User Stories Flattened
    const storiesHeader = ['Etapa', 'Usuário', 'Prioridade', 'História'];
    const storiesData: any[] = [];
    data.steps.forEach(step => {
        step.userCards.forEach(card => {
            card.stories.forEach(story => {
                storiesData.push([
                    step.name,
                    card.userName,
                    story.priority,
                    story.text
                ]);
            });
        });
    });
    const wsStories = XLSX.utils.aoa_to_sheet([storiesHeader, ...storiesData]);
    XLSX.utils.book_append_sheet(wb, wsStories, "Histórias");

    XLSX.writeFile(wb, `${data.title || 'processo'}.xlsx`);
};

