import path from 'path';
import { fileURLToPath } from 'url';
import { defineConfig, loadEnv } from 'vite';
import react from '@vitejs/plugin-react';

const __filename = fileURLToPath(import.meta.url);
const __dirname = path.dirname(__filename);

export default defineConfig(({ mode }) => {
    const env = loadEnv(mode, '.', '');
    return {
      server: {
        port: 3000,
        host: '0.0.0.0',
      },
      plugins: [react()],
      define: {
        'process.env.API_KEY': JSON.stringify(env.GEMINI_API_KEY),
        'process.env.GEMINI_API_KEY': JSON.stringify(env.GEMINI_API_KEY)
      },
      resolve: {
        alias: {
          '@': path.resolve(__dirname, '.'),
        }
      }
    };
});

import { ProcessImprovement, ProcessStep } from "../types/process";
import { generateId } from "../lib/utils";
import * as XLSX from 'xlsx';
import jsPDF from 'jspdf';
import autoTable from 'jspdf-autotable';

const STORAGE_KEY = 'process_improvement_data_v1';

export const getEmptyProcess = (): ProcessImprovement => ({
    id: generateId(),
    title: '',
    theme: '',
    sectors: '',
    managers: '',
    steps: [],
    updatedAt: new Date().toISOString()
});

export const saveToLocalStorage = (data: ProcessImprovement) => {
    try {
        localStorage.setItem(STORAGE_KEY, JSON.stringify(data));
        console.log('Saved to local storage');
    } catch (e) {
        console.error('Failed to save', e);
    }
};

export const loadFromLocalStorage = (): ProcessImprovement => {
    try {
        const data = localStorage.getItem(STORAGE_KEY);
        if (data) return JSON.parse(data);
    } catch (e) {
        console.error('Failed to load', e);
    }
    return getEmptyProcess();
};

export const exportToJson = (data: ProcessImprovement) => {
    const blob = new Blob([JSON.stringify(data, null, 2)], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = `${data.title || 'processo'}.json`;
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
};

export const exportToCSV = (data: ProcessImprovement) => {
    const headers = ['Etapa #', 'Nome', 'Como é hoje', 'Como será', 'Sem Melhoria', 'Usuário', 'Prioridade', 'História'];
    const rows: string[][] = [];

    data.steps.forEach((step, index) => {
        const baseRow = [
            (index + 1).toString(),
            step.name,
            step.currentScenario,
            step.noImprovement ? 'Sim' : 'Não',
            step.noImprovement ? 'N/A' : step.futureScenario
        ];

        if (step.userCards.length === 0) {
            rows.push([...baseRow, '', '', '']);
        } else {
            step.userCards.forEach(card => {
                if (card.stories.length === 0) {
                    rows.push([...baseRow, card.userName, '', '']);
                } else {
                    card.stories.forEach(story => {
                        rows.push([
                            ...baseRow,
                            card.userName,
                            story.priority,
                            story.text
                        ]);
                    });
                }
            });
        }
    });

    let csvContent = "data:text/csv;charset=utf-8," 
        + headers.join(",") + "\n" 
        + rows.map(e => e.map(cell => `"${(cell || '').replace(/"/g, '""')}"`).join(",")).join("\n");

    const encodedUri = encodeURI(csvContent);
    const link = document.createElement("a");
    link.setAttribute("href", encodedUri);
    link.setAttribute("download", `${data.title || 'processo'}.csv`);
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
};

export const exportToXLSX = (data: ProcessImprovement) => {
    const wb = XLSX.utils.book_new();

    // Sheet 1: Info
    const infoData = [
        ['Título', data.title],
        ['Tema', data.theme],
        ['Setores', data.sectors],
        ['Gestores', data.managers],
        ['Data', new Date().toLocaleDateString()]
    ];
    const wsInfo = XLSX.utils.aoa_to_sheet(infoData);
    XLSX.utils.book_append_sheet(wb, wsInfo, "Informações");

    // Sheet 2: Steps
    const stepsHeader = ['#', 'Nome', 'Como é hoje', 'Como será', 'Sem Melhoria'];
    const stepsData = data.steps.map((step, i) => [
        i + 1,
        step.name,
        step.currentScenario,
        step.futureScenario,
        step.noImprovement ? 'Sim' : 'Não'
    ]);
    const wsSteps = XLSX.utils.aoa_to_sheet([stepsHeader, ...stepsData]);
    XLSX.utils.book_append_sheet(wb, wsSteps, "Etapas");

    // Sheet 3: User Stories Flattened
    const storiesHeader = ['Etapa', 'Usuário', 'Prioridade', 'História'];
    const storiesData: any[] = [];
    data.steps.forEach(step => {
        step.userCards.forEach(card => {
            card.stories.forEach(story => {
                storiesData.push([
                    step.name,
                    card.userName,
                    story.priority,
                    story.text
                ]);
            });
        });
    });
    const wsStories = XLSX.utils.aoa_to_sheet([storiesHeader, ...storiesData]);
    XLSX.utils.book_append_sheet(wb, wsStories, "Histórias");

    XLSX.writeFile(wb, `${data.title || 'processo'}.xlsx`);
};

