export const exportToXLSX = (data: ProcessImprovement) => {
    const wb = XLSX.utils.book_new();

    // Aba 1: Resumo do Projeto
    const infoData = [
        ['RESUMO DO PROJETO DE MELHORIA'],
        [''],
        ['Título', data.title],
        ['Tema', data.theme],
        ['Setores', data.sectors],
        ['Gestores', data.managers],
        ['Última Atualização', new Date(data.updatedAt).toLocaleString()]
    ];
    const wsInfo = XLSX.utils.aoa_to_sheet(infoData);
    XLSX.utils.book_append_sheet(wb, wsInfo, "Resumo");

    // Aba 2: Etapas e Cenários
    const stepsHeader = ['Ordem', 'Etapa', 'Cenário Atual (AS-IS)', 'Cenário Futuro (TO-BE)', 'Status'];
    const stepsData = data.steps.map((step, i) => [
        i + 1,
        step.name,
        step.currentScenario,
        step.noImprovement ? 'MANTER PROCESSO ATUAL' : step.futureScenario,
        step.noImprovement ? 'Sem Alteração' : 'Com Melhoria'
    ]);
    const wsSteps = XLSX.utils.aoa_to_sheet([stepsHeader, ...stepsData]);
    XLSX.utils.book_append_sheet(wb, wsSteps, "Fluxo de Processo");

    // Aba 3: Histórias de Usuário (Requisitos)
    const storiesHeader = ['Etapa Relacionada', 'Usuário/Papel', 'Prioridade', 'História (Requisito)'];
    const storiesData: any[] = [];
    data.steps.forEach(step => {
        step.userCards.forEach(card => {
            card.stories.forEach(story => {
                storiesData.push([
                    step.name || 'Etapa sem nome',
                    card.userName || 'Não especificado',
                    story.priority,
                    story.text
                ]);
            });
        });
    });
    const wsStories = XLSX.utils.aoa_to_sheet([storiesHeader, ...storiesData]);
    XLSX.utils.book_append_sheet(wb, wsStories, "Requisitos Detalhados");

    XLSX.writeFile(wb, `RELATORIO_${data.title.replace(/\s+/g, '_')}.xlsx`);
};

export const exportToPDF = (data: ProcessImprovement) => {
    const doc = new jsPDF();
    const primaryColor = [15, 95, 135]; // #0F5F87

    // Cabeçalho PDF
    doc.setFillColor(primaryColor[0], primaryColor[1], primaryColor[2]);
    doc.rect(0, 0, 210, 40, 'F');

    doc.setTextColor(255, 255, 255);
    doc.setFontSize(22);
    doc.text(data.title.toUpperCase() || 'PROJETO DE MELHORIA', 14, 25);

    doc.setFontSize(10);
    doc.text(`Gerado em: ${new Date().toLocaleDateString()}`, 14, 34);

    // Info Section
    doc.setTextColor(40, 40, 40);
    doc.setFontSize(12);
    doc.setFont("helvetica", "bold");
    doc.text("INFORMAÇÕES GERAIS", 14, 50);
    doc.setDrawColor(200, 200, 200);
    doc.line(14, 52, 196, 52);

    doc.setFont("helvetica", "normal");
    doc.setFontSize(10);
    doc.text(`TEMA: ${data.theme || 'N/A'}`, 14, 60);
    doc.text(`SETORES: ${data.sectors || 'N/A'}`, 14, 66);
    doc.text(`GESTORES: ${data.managers || 'N/A'}`, 14, 72);

    // Tabela de Etapas
    const tableRows = data.steps.map((step, i) => [
        (i + 1).toString(),
        step.name || 'Sem Nome',
        step.currentScenario || '-',
        step.noImprovement ? '[SEM ALTERAÇÃO]' : (step.futureScenario || '-'),
        step.userCards.length.toString()
    ]);

    autoTable(doc, {
        head: [['#', 'ETAPA', 'CENÁRIO ATUAL', 'PROPOSTA DE MELHORIA', 'REQUISITOS']],
        body: tableRows,
        startY: 80,
        theme: 'grid',
        headStyles: { fillColor: primaryColor as any, fontSize: 9 },
        styles: { fontSize: 8, cellPadding: 3 },
        columnStyles: {
            0: { cellWidth: 10 },
            1: { cellWidth: 35 },
            2: { cellWidth: 60 },
            3: { cellWidth: 60 },
            4: { cellWidth: 20 }
        }
    });

    doc.save(`PDF_${data.title.replace(/\s+/g, '_')}.pdf`);
};

import React, { useState, useEffect } from 'react';
import { ProcessHeader } from './components/ProcessHeader';
import { ProcessTable } from './components/ProcessTable';
import { ExportButtons } from './components/ExportButtons';
import { ProcessImprovement } from './types/process';
import { loadFromLocalStorage, saveToLocalStorage, validateProcessJson } from './utils/exportUtils';
import { FileWarning, CheckCircle } from 'lucide-react';

function App() {
  const [data, setData] = useState<ProcessImprovement | null>(null);
  const [notification, setNotification] = useState<{message: string, type: 'success' | 'error'} | null>(null);

  useEffect(() => {
    const loadedData = loadFromLocalStorage();
    setData(loadedData);
  }, []);

  useEffect(() => {
    if (data) {
      const timeoutId = setTimeout(() => {
        saveToLocalStorage({ ...data, updatedAt: new Date().toISOString() });
      }, 1000);
      return () => clearTimeout(timeoutId);
    }
  }, [data]);

  const showNotification = (message: string, type: 'success' | 'error') => {
    setNotification({ message, type });
    setTimeout(() => setNotification(null), 3000);
  };

  const handleUpdate = (field: keyof ProcessImprovement, value: any) => {
    if (!data) return;
    setData({ ...data, [field]: value });
  };

  const handleFullUpdate = (newData: ProcessImprovement) => {
    setData(newData);
  };

  const handleImport = (e: React.ChangeEvent<HTMLInputElement>) => {
      const file = e.target.files?.[0];
      if (file) {
          const reader = new FileReader();
          reader.onload = (event) => {
              try {
                  const importedData = JSON.parse(event.target?.result as string);
                  if (validateProcessJson(importedData)) {
                      setData(importedData);
                      showNotification('Projeto carregado com sucesso!', 'success');
                  } else {
                      showNotification('Arquivo JSON inválido ou corrompido.', 'error');
                  }
              } catch (error) {
                  showNotification('Erro na leitura do arquivo.', 'error');
              }
          };
          reader.readAsText(file);
      }
      // Reset input value to allow importing the same file again if needed
      e.target.value = '';
  };

  if (!data) return (
    <div className="flex flex-col items-center justify-center h-screen bg-slate-50 gap-4">
      <div className="w-12 h-12 border-4 border-brand border-t-transparent rounded-full animate-spin"></div>
      <p className="text-slate-500 font-medium animate-pulse">Iniciando ProcessFlow...</p>
    </div>
  );

  return (
    <div className="min-h-screen bg-[#f1f5f9] pb-24 font-sans text-slate-900 selection:bg-brand-100">

      {/* Toast Notification */}
      {notification && (
        <div className={`fixed top-6 right-6 z-50 flex items-center gap-3 px-6 py-3 rounded-lg shadow-2xl animate-in slide-in-from-right-10 border ${
          notification.type === 'success' ? 'bg-white border-green-100 text-green-800' : 'bg-white border-red-100 text-red-800'
        }`}>
          {notification.type === 'success' ? <CheckCircle className="w-5 h-5 text-green-500" /> : <FileWarning className="w-5 h-5 text-red-500" />}
          <span className="font-semibold text-sm">{notification.message}</span>
        </div>
      )}

      <div className="max-w-[1400px] mx-auto p-4 md:p-8 space-y-8">

        {/* Top Actions Bar */}
        <div className="flex flex-col md:flex-row items-start md:items-center justify-between gap-4 bg-white p-4 rounded-xl border border-slate-200 shadow-sm">
           <div className="flex items-center gap-2">
              <div className="w-2 h-8 bg-brand rounded-full"></div>
              <div>
                <h1 className="text-sm font-bold text-slate-400 uppercase tracking-tighter">Projeto Ativo</h1>
                <p className="text-lg font-bold text-slate-700 truncate max-w-[300px]">{data.title || 'Sem Título'}</p>
              </div>
           </div>
           <ExportButtons data={data} onImport={handleImport} />
        </div>

        <ProcessHeader 
          data={data} 
          onUpdate={handleUpdate} 
        />

        <div className="bg-white rounded-2xl shadow-xl shadow-slate-200/50 border border-slate-200 overflow-hidden">
           <div className="p-6 md:p-8">
              <ProcessTable 
                data={data} 
                onUpdate={handleFullUpdate} 
              />
           </div>
        </div>

        <div className="flex flex-col items-center gap-2 text-slate-400 mt-12 mb-8">
           <div className="flex items-center gap-4 text-xs font-medium bg-white px-4 py-2 rounded-full border border-slate-200 shadow-sm">
              <span className="flex items-center gap-1"><kbd className="bg-slate-100 px-1.5 py-0.5 rounded border border-slate-300">Click</kbd> para editar</span>
              <span className="w-1 h-1 bg-slate-300 rounded-full"></span>
              <span className="flex items-center gap-1"><kbd className="bg-slate-100 px-1.5 py-0.5 rounded border border-slate-300">Drag</kbd> para reordenar</span>
           </div>
           <p className="text-[10px] uppercase tracking-widest font-bold opacity-50">ProcessFlow Improvement Tool &copy; 2025</p>
        </div>
      </div>
    </div>
  );
}

export default App;

