import React, { useState, useEffect } from 'react';
import { ProcessHeader } from './components/ProcessHeader';
import { Timeline } from './components/Timeline';
import { StepDetails } from './components/StepDetails';
import { ProcessImprovement, ProcessStep } from './types/process';
import { loadFromLocalStorage, saveToLocalStorage, validateProcessJson, getEmptyProcess } from './utils/exportUtils';
import { generateId } from './lib/utils';
import { FileWarning, CheckCircle } from 'lucide-react';

function App() {
  const [data, setData] = useState<ProcessImprovement | null>(null);
  const [selectedStepId, setSelectedStepId] = useState<string | null>(null);
  const [notification, setNotification] = useState<{message: string, type: 'success' | 'error'} | null>(null);

  useEffect(() => {
    const loadedData = loadFromLocalStorage();
    setData(loadedData);
    if (loadedData.steps.length > 0) {
        setSelectedStepId(loadedData.steps[0].id);
    }
  }, []);

  useEffect(() => {
    if (data) {
      const timeoutId = setTimeout(() => {
        saveToLocalStorage({ ...data, updatedAt: new Date().toISOString() });
      }, 1000);
      return () => clearTimeout(timeoutId);
    }
  }, [data]);

  const showNotification = (message: string, type: 'success' | 'error') => {
    setNotification({ message, type });
    setTimeout(() => setNotification(null), 3000);
  };

  const handleUpdate = (field: keyof ProcessImprovement, value: any) => {
    if (!data) return;
    setData({ ...data, [field]: value });
  };

  const handleImport = (e: React.ChangeEvent<HTMLInputElement>) => {
      const file = e.target.files?.[0];
      if (file) {
          const reader = new FileReader();
          reader.onload = (event) => {
              try {
                  const importedData = JSON.parse(event.target?.result as string);
                  if (validateProcessJson(importedData)) {
                      setData(importedData);
                      if(importedData.steps.length > 0) setSelectedStepId(importedData.steps[0].id);
                      showNotification('Projeto carregado com sucesso!', 'success');
                  } else {
                      showNotification('Arquivo JSON inválido ou corrompido.', 'error');
                  }
              } catch (error) {
                  showNotification('Erro na leitura do arquivo.', 'error');
              }
          };
          reader.readAsText(file);
      }
      e.target.value = '';
  };

  const updateSteps = (newSteps: ProcessStep[]) => {
      if (!data) return;
      setData({ ...data, steps: newSteps });
  };

  const handleAddStep = () => {
      if (!data) return;
      const newStep: ProcessStep = {
          id: generateId(),
          name: 'Nova Etapa',
          role: '',
          currentScenario: '',
          futureScenario: '',
          idealScenario: '',
          noImprovement: false,
          userCards: []
      };
      const newSteps = [...data.steps, newStep];
      setData({ ...data, steps: newSteps });
      setSelectedStepId(newStep.id);
  };

  const handleUpdateSelectedStep = (updatedStep: ProcessStep) => {
      if (!data) return;
      const newSteps = data.steps.map(s => s.id === updatedStep.id ? updatedStep : s);
      setData({ ...data, steps: newSteps });
  }

  if (!data) return null;

  const selectedStep = data.steps.find(s => s.id === selectedStepId);

  return (
    <div className="flex flex-col h-screen w-screen bg-[#f1f5f9] overflow-hidden">

      {/* Toast Notification */}
      {notification && (
        <div className={`fixed top-6 right-6 z-50 flex items-center gap-3 px-6 py-3 rounded-lg shadow-2xl animate-in slide-in-from-right-10 border ${
          notification.type === 'success' ? 'bg-white border-green-100 text-green-800' : 'bg-white border-red-100 text-red-800'
        }`}>
          {notification.type === 'success' ? <CheckCircle className="w-5 h-5 text-green-500" /> : <FileWarning className="w-5 h-5 text-red-500" />}
          <span className="font-semibold text-sm">{notification.message}</span>
        </div>
      )}

      {/* 1. HEADER (Fixed) */}
      <ProcessHeader 
        data={data} 
        onUpdate={handleUpdate} 
        onImport={handleImport}
      />

      {/* 2. TIMELINE (Fixed Height) */}
      <Timeline 
        steps={data.steps}
        selectedStepId={selectedStepId}
        onSelectStep={setSelectedStepId}
        onUpdateSteps={updateSteps}
        onAddStep={handleAddStep}
      />

      {/* 3. DETAILS AREA (Flexible) */}
      {selectedStep ? (
        <StepDetails 
            key={selectedStep.id} // Force re-render on step switch to reset scroll
            step={selectedStep}
            onUpdate={handleUpdateSelectedStep}
        />
      ) : (
        <div className="flex-1 flex items-center justify-center text-slate-400">
            Selecione ou crie uma etapa para começar.
        </div>
      )}

    </div>
  );
}

export default App;

import React, { useState } from 'react';
import { ProcessImprovement, ProcessStep } from '../types/process';
import { ProcessStepRow } from './ProcessStepRow';
import { Button } from './ui/button';
import { Plus, List } from 'lucide-react';
import { generateId } from '../lib/utils';
import {
  DndContext, 
  closestCenter,
  KeyboardSensor,
  PointerSensor,
  useSensor,
  useSensors,
  DragEndEvent
} from '@dnd-kit/core';
import {
  arrayMove,
  SortableContext,
  sortableKeyboardCoordinates,
  verticalListSortingStrategy,
} from '@dnd-kit/sortable';

interface ProcessTableProps {
  data: ProcessImprovement;
  onUpdate: (newData: ProcessImprovement) => void;
}

export const ProcessTable: React.FC<ProcessTableProps> = ({ data, onUpdate }) => {
  const [showNoImprovement, setShowNoImprovement] = useState(true);

  const sensors = useSensors(
    useSensor(PointerSensor),
    useSensor(KeyboardSensor, {
      coordinateGetter: sortableKeyboardCoordinates,
    })
  );

  const handleDragEnd = (event: DragEndEvent) => {
    const { active, over } = event;

    if (over && active.id !== over.id) {
      const oldIndex = data.steps.findIndex((step) => step.id === active.id);
      const newIndex = data.steps.findIndex((step) => step.id === over.id);

      const newSteps = arrayMove(data.steps, oldIndex, newIndex);
      onUpdate({ ...data, steps: newSteps });
    }
  };

  const addStep = () => {
    const newStep: ProcessStep = {
      id: generateId(),
      name: '',
      role: '',
      currentScenario: '',
      futureScenario: '',
      idealScenario: '',
      noImprovement: false,
      userCards: []
    };
    onUpdate({ ...data, steps: [...data.steps, newStep] });
  };

  const updateStep = (index: number, updatedStep: ProcessStep) => {
    const newSteps = [...data.steps];
    newSteps[index] = updatedStep;
    onUpdate({ ...data, steps: newSteps });
  };

  const deleteStep = (index: number) => {
    if (confirm('Tem certeza que deseja excluir esta etapa e todas as suas histórias?')) {
      const newSteps = data.steps.filter((_, i) => i !== index);
      onUpdate({ ...data, steps: newSteps });
    }
  };

  const visibleSteps = showNoImprovement 
    ? data.steps 
    : data.steps.filter(s => !s.noImprovement);

  const countNoImprovement = data.steps.filter(s => s.noImprovement).length;

  return (
    <div className="space-y-4">
      <div className="flex items-center justify-between pb-2">
        <h2 className="text-lg font-bold text-slate-800 flex items-center gap-2">
            <List className="w-5 h-5 text-[#0F5F87]" />
            Etapas do Processo
        </h2>
        <div className="flex items-center gap-3">
             <label className="text-sm text-slate-500 font-medium cursor-pointer flex items-center gap-2 select-none">
                <div 
                  className={`w-10 h-5 rounded-full relative transition-colors ${showNoImprovement ? 'bg-[#0F5F87]' : 'bg-slate-300'}`}
                  onClick={() => setShowNoImprovement(!showNoImprovement)}
                >
                    <div className={`absolute top-1 w-3 h-3 bg-white rounded-full transition-all ${showNoImprovement ? 'left-6' : 'left-1'}`} />
                </div>
                <span>Sem melhoria ({countNoImprovement})</span>
             </label>
        </div>
      </div>

      {/* Table Headers */}
      <div className="grid grid-cols-12 gap-4 px-4 py-2 bg-slate-100/50 rounded-lg text-sm font-semibold text-slate-600 border border-transparent">
          <div className="col-span-12 md:col-span-3 lg:col-span-3 pl-8">Etapa Nome</div>
          <div className="hidden md:block md:col-span-4 lg:col-span-4">Como é Hoje</div>
          <div className="hidden md:block md:col-span-4 lg:col-span-4">Como Será</div>
      </div>

      <DndContext 
        sensors={sensors}
        collisionDetection={closestCenter}
        onDragEnd={handleDragEnd}
      >
        <SortableContext 
          items={visibleSteps.map(s => s.id)}
          strategy={verticalListSortingStrategy}
        >
          <div className="space-y-3">
            {visibleSteps.map((step) => {
                const realIndex = data.steps.findIndex(s => s.id === step.id);
                return (
                    <ProcessStepRow 
                        key={step.id} 
                        step={step} 
                        index={realIndex}
                        onUpdate={(updated) => updateStep(realIndex, updated)}
                        onDelete={() => deleteStep(realIndex)}
                    />
                )
            })}
          </div>
        </SortableContext>
      </DndContext>

      <Button 
        onClick={addStep} 
        variant="outline" 
        className="w-full border-dashed border-2 border-slate-300 py-6 text-[#0F5F87] font-semibold hover:border-[#0F5F87] hover:bg-slate-50 transition-all rounded-xl"
      >
        <Plus className="w-5 h-5 mr-2" />
        Adicionar Nova Etapa
      </Button>
    </div>
  );
};

import React from 'react';
import { ProcessStep } from '../types/process';
import { EditableText } from './EditableText';
import { GripVertical, Plus, Trash2, Settings2 } from 'lucide-react';
import { cn } from '../lib/utils';
import {
  DndContext, 
  closestCenter,
  KeyboardSensor,
  PointerSensor,
  useSensor,
  useSensors,
  DragEndEvent
} from '@dnd-kit/core';
import {
  arrayMove,
  SortableContext,
  sortableKeyboardCoordinates,
  horizontalListSortingStrategy,
  useSortable
} from '@dnd-kit/sortable';
import { CSS } from '@dnd-kit/utilities';

interface TimelineProps {
  steps: ProcessStep[];
  selectedStepId: string | null;
  onSelectStep: (id: string) => void;
  onUpdateSteps: (steps: ProcessStep[]) => void;
  onAddStep: () => void;
}

interface SortableStepProps {
  step: ProcessStep;
  index: number;
  isSelected: boolean;
  onSelect: () => void;
  onUpdate: (val: string, field: 'name' | 'role') => void;
  onDelete: () => void;
}

const SortableStep: React.FC<SortableStepProps> = ({ step, index, isSelected, onSelect, onUpdate, onDelete }) => {
    const {
        attributes,
        listeners,
        setNodeRef,
        transform,
        transition,
        isDragging
    } = useSortable({ id: step.id });

    const style = {
        transform: CSS.Transform.toString(transform),
        transition,
        zIndex: isDragging ? 50 : 'auto',
    };

    return (
        <div 
            ref={setNodeRef} 
            style={style}
            className="flex flex-col items-center justify-start h-full min-w-[200px] max-w-[200px] group relative pt-4"
        >
            {/* Card Superior (Role + Name) */}
            <div 
                onClick={onSelect}
                className={cn(
                    "w-[90%] p-3 rounded-xl border-2 transition-all duration-200 cursor-pointer flex flex-col gap-1 relative bg-white shadow-sm hover:shadow-md",
                    isSelected 
                        ? "border-blue-600 ring-4 ring-blue-50 -translate-y-1 z-10" 
                        : "border-slate-200 hover:border-blue-300"
                )}
            >
                {/* Drag Handle & Delete (Hover only) */}
                <div className="absolute -top-3 right-0 left-0 flex justify-center opacity-0 group-hover:opacity-100 transition-opacity gap-1">
                    <button {...attributes} {...listeners} className="bg-slate-800 text-white p-1 rounded cursor-grab active:cursor-grabbing shadow-sm">
                        <GripVertical size={12} />
                    </button>
                    <button onClick={(e) => { e.stopPropagation(); onDelete(); }} className="bg-red-100 text-red-600 p-1 rounded hover:bg-red-200 shadow-sm border border-red-200">
                        <Trash2 size={12} />
                    </button>
                </div>

                {/* Conteúdo do Card */}
                <div className="flex flex-col h-full">
                    <div className="mb-1">
                        <EditableText
                            value={step.role}
                            onChange={(val) => onUpdate(val, 'role')}
                            placeholder="DEFINIR PAPEL/SETOR"
                            className="text-[10px] font-bold uppercase text-slate-500 bg-slate-50 px-1 rounded w-full text-center"
                        />
                    </div>
                    <div className="flex-1 flex items-center justify-center text-center">
                        <EditableText
                            value={step.name}
                            onChange={(val) => onUpdate(val, 'name')}
                            placeholder="Nome da Etapa"
                            className={cn(
                                "text-xs font-bold leading-tight w-full text-center",
                                isSelected ? "text-blue-900" : "text-slate-700"
                            )}
                        />
                    </div>
                </div>

                {/* Seta indicativa se selecionado */}
                {isSelected && (
                    <div className="absolute left-1/2 -bottom-2.5 -translate-x-1/2 w-0 h-0 border-l-[8px] border-l-transparent border-r-[8px] border-r-transparent border-t-[8px] border-t-blue-600"></div>
                )}
            </div>

            {/* Linha e Conector */}
            <div className="h-12 w-full flex flex-col items-center justify-center relative shrink-0">
                <div className={cn(
                    "w-full h-1 absolute top-1/2 -translate-y-1/2",
                    isSelected ? "bg-blue-200" : "bg-slate-200"
                )}></div>
                <div className={cn(
                    "w-6 h-6 rounded-full border-4 z-10 flex items-center justify-center text-[10px] font-bold transition-all",
                    isSelected 
                        ? "bg-blue-600 border-white ring-2 ring-blue-200 text-white scale-110" 
                        : "bg-white border-slate-300 text-slate-400"
                )}>
                    {index + 1}
                </div>
            </div>
        </div>
    );
}

export const Timeline: React.FC<TimelineProps> = ({ steps, selectedStepId, onSelectStep, onUpdateSteps, onAddStep }) => {

    const sensors = useSensors(
        useSensor(PointerSensor, { activationConstraint: { distance: 5 } }),
        useSensor(KeyboardSensor, { coordinateGetter: sortableKeyboardCoordinates })
    );

    const handleDragEnd = (event: DragEndEvent) => {
        const { active, over } = event;
        if (over && active.id !== over.id) {
            const oldIndex = steps.findIndex((s) => s.id === active.id);
            const newIndex = steps.findIndex((s) => s.id === over.id);
            onUpdateSteps(arrayMove(steps, oldIndex, newIndex));
        }
    };

    const handleUpdateStep = (id: string, val: string, field: 'name' | 'role') => {
        const newSteps = steps.map(s => s.id === id ? { ...s, [field]: val } : s);
        onUpdateSteps(newSteps);
    };

    const handleDeleteStep = (id: string) => {
        if(confirm("Remover esta etapa?")) {
            const newSteps = steps.filter(s => s.id !== id);
            onUpdateSteps(newSteps);
            if (selectedStepId === id && newSteps.length > 0) {
                onSelectStep(newSteps[0].id);
            }
        }
    }

    return (
        <div className="flex-shrink-0 bg-white border-b border-slate-200 h-[220px] relative flex flex-col">
            <div className="absolute top-0 left-0 bg-slate-50 px-3 py-1 rounded-br-lg text-[10px] font-bold text-slate-400 border-b border-r border-slate-200 z-20 flex items-center gap-1">
                <Settings2 size={12} /> TIMELINE DO PROCESSO
            </div>

            <div className="flex-1 overflow-x-auto custom-scrollbar flex items-center px-8 relative">
                <DndContext sensors={sensors} collisionDetection={closestCenter} onDragEnd={handleDragEnd}>
                    <SortableContext items={steps.map(s => s.id)} strategy={horizontalListSortingStrategy}>
                        <div className="flex items-start h-full pt-8 pb-4">
                            {steps.map((step, index) => (
                                <SortableStep
                                    key={step.id}
                                    step={step}
                                    index={index}
                                    isSelected={selectedStepId === step.id}
                                    onSelect={() => onSelectStep(step.id)}
                                    onUpdate={(val, field) => handleUpdateStep(step.id, val, field)}
                                    onDelete={() => handleDeleteStep(step.id)}
                                />
                            ))}

                            {/* Add Button */}
                            <div className="h-full flex items-center justify-center pl-4 pr-12 min-w-[100px]">
                                <button 
                                    onClick={onAddStep}
                                    className="group flex flex-col items-center gap-2 text-slate-300 hover:text-blue-600 transition-colors"
                                >
                                    <div className="w-10 h-10 rounded-full border-2 border-dashed border-current flex items-center justify-center group-hover:bg-blue-50">
                                        <Plus size={20} />
                                    </div>
                                    <span className="text-xs font-bold uppercase">Adicionar</span>
                                </button>
                            </div>
                        </div>
                    </SortableContext>
                </DndContext>
            </div>
        </div>
    );
};

