const ListEditor: React.FC<{
    items: string[];
    onChange: (items: string[]) => void;
    placeholder: string;
    icon?: React.ReactNode;
    colorClass?: string;
}> = ({ items = [], onChange, placeholder, icon, colorClass = "text-slate-600" }) => {
    const [newItem, setNewItem] = useState("");

    const handleAdd = () => {
        if (newItem.trim()) {
            onChange([...items, newItem.trim()]);
            setNewItem("");
        }
    };

    const handleKeyDown = (e: React.KeyboardEvent) => {
        if (e.key === 'Enter') handleAdd();
    };

    const handleRemove = (index: number) => {
        onChange(items.filter((_, i) => i !== index));
    };

    return (
        <div className="flex flex-col h-full bg-slate-50 rounded-lg border border-slate-200 overflow-hidden">
            {/* Header / Input */}
            <div className="p-2 border-b border-slate-200 bg-white">
                 <div className="flex gap-2">
                    <Input 
                        value={newItem}
                        onChange={(e) => setNewItem(e.target.value)}
                        onKeyDown={handleKeyDown}
                        placeholder={placeholder}
                        className="h-8 text-xs"
                    />
                    <Button onClick={handleAdd} size="icon" className="h-8 w-8 bg-slate-100 hover:bg-slate-200 text-slate-600">
                        <Plus size={14} />
                    </Button>
                 </div>
            </div>

