export type StoryPriority = 'Essencial' | 'Deveria ter' | 'Poderia ter';

export interface UserStory {
  id: string;
  text: string;
  priority: StoryPriority;
}

export interface UserCard {
  id: string;
  userName: string;
  stories: UserStory[];
}

export interface ProcessStep {
  id: string;
  name: string;
  role: string; // Papel/Setor Responsável
  currentScenario: string; // Como é hoje
  futureScenario: string; // Como será
  idealScenario: string; // Como poderia ser (Ideal)
  inputs: string[]; // Novo: Entradas do processo
  outputs: string[]; // Novo: Saídas do processo
  noImprovement: boolean;
  userCards: UserCard[];
}

export interface Deliverable {
  id: string;
  title: string;
  description: string;
  linkedStoryIds: string[]; // IDs das histórias vinculadas a este entregável
}

export interface ProcessImprovement {
  id: string;
  title: string;
  theme: string;
  sectors: string;
  managers: string;
  steps: ProcessStep[];
  deliverables: Deliverable[]; // Lista de entregáveis do projeto
  updatedAt: string;
}

import { ProcessImprovement } from "../types/process";
import { generateId } from "../lib/utils";
import * as XLSX from 'xlsx';
import jsPDF from 'jspdf';
import autoTable from 'jspdf-autotable';

const STORAGE_KEY = 'process_improvement_data_v2'; // Versão atualizada do storage

export const getEmptyProcess = (): ProcessImprovement => ({
    id: generateId(),
    title: 'Novo Processo de Melhoria',
    theme: '',
    sectors: '',
    managers: '',
    steps: [
        {
            id: generateId(),
            name: 'Início do Processo',
            role: 'Solicitante',
            currentScenario: '',
            futureScenario: '',
            idealScenario: '',
            inputs: [],
            outputs: [],
            noImprovement: false,
            userCards: []
        }
    ],
    deliverables: [],
    updatedAt: new Date().toISOString()
});

export const saveToLocalStorage = (data: ProcessImprovement) => {
    try {
        localStorage.setItem(STORAGE_KEY, JSON.stringify(data));
    } catch (e) {
        console.error('Erro ao salvar no cache local', e);
    }
};

export const loadFromLocalStorage = (): ProcessImprovement => {
    try {
        const data = localStorage.getItem(STORAGE_KEY);
        if (data) {
            const parsed = JSON.parse(data);
            // Migração para garantir que campos novos existam
            parsed.steps = parsed.steps.map((s: any) => ({
                ...s,
                role: s.role || '',
                idealScenario: s.idealScenario || '',
                inputs: s.inputs || [],
                outputs: s.outputs || []
            }));
            // Migração para deliverables
            if (!parsed.deliverables) {
                parsed.deliverables = [];
            }
            return parsed;
        }
    } catch (e) {
        console.error('Erro ao carregar do cache local', e);
    }
    return getEmptyProcess();
};

export const exportToJson = (data: ProcessImprovement) => {
    const blob = new Blob([JSON.stringify(data, null, 2)], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = `PROJETO_${data.title.replace(/\s+/g, '_')}_${new Date().toISOString().split('T')[0]}.json`;
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
};

export const validateProcessJson = (data: any): data is ProcessImprovement => {
    return data && typeof data === 'object' && Array.isArray(data.steps) && typeof data.title === 'string';
};

export const exportToXLSX = (data: ProcessImprovement) => {
    const wb = XLSX.utils.book_new();

    // Aba 1: Resumo do Projeto
    const infoData = [
        ['RESUMO DO PROJETO DE MELHORIA'],
        [''],
        ['Título', data.title],
        ['Setores', data.sectors],
        ['Gestores', data.managers],
        ['Última Atualização', new Date(data.updatedAt).toLocaleString()]
    ];
    const wsInfo = XLSX.utils.aoa_to_sheet(infoData);
    XLSX.utils.book_append_sheet(wb, wsInfo, "Resumo");

    // Aba 2: Detalhe do Processo (Visão Geral)
    const detailHeader = ['Ordem', 'Etapa', 'Responsável', 'Entradas', 'Processo Atual (AS-IS)', 'Saídas'];
    const detailData = data.steps.map((step, i) => [
        i + 1,
        step.name,
        step.role,
        step.inputs?.join('\n') || '',
        step.currentScenario,
        step.outputs?.join('\n') || ''
    ]);
    const wsDetail = XLSX.utils.aoa_to_sheet([detailHeader, ...detailData]);
    XLSX.utils.book_append_sheet(wb, wsDetail, "Mapeamento Atual");

    // Aba 3: Cenários Futuros
    const stepsHeader = ['Ordem', 'Etapa', 'Cenário Atual (AS-IS)', 'Cenário Futuro (TO-BE)', 'Cenário Ideal (COULD-BE)'];
    const stepsData = data.steps.map((step, i) => [
        i + 1,
        step.name,
        step.currentScenario,
        step.noImprovement ? 'MANTER PROCESSO ATUAL' : step.futureScenario,
        step.idealScenario
    ]);
    const wsSteps = XLSX.utils.aoa_to_sheet([stepsHeader, ...stepsData]);
    XLSX.utils.book_append_sheet(wb, wsSteps, "Melhorias Propostas");

    // Aba 4: Histórias de Usuário
    const storiesHeader = ['Etapa Relacionada', 'Usuário/Papel', 'Prioridade', 'História (Requisito)'];
    const storiesData: any[] = [];
    data.steps.forEach(step => {
        step.userCards.forEach(card => {
            card.stories.forEach(story => {
                storiesData.push([
                    step.name || 'Etapa sem nome',
                    card.userName || 'Não especificado',
                    story.priority,
                    story.text
                ]);
            });
        });
    });
    const wsStories = XLSX.utils.aoa_to_sheet([storiesHeader, ...storiesData]);
    XLSX.utils.book_append_sheet(wb, wsStories, "Requisitos Detalhados");

    // Aba 5: Entregáveis (Novo)
    if (data.deliverables && data.deliverables.length > 0) {
        const delivHeader = ['Entregável', 'Descrição', 'Qtd Histórias'];
        const delivData = data.deliverables.map(d => [
            d.title,
            d.description,
            d.linkedStoryIds.length
        ]);
        const wsDeliv = XLSX.utils.aoa_to_sheet([delivHeader, ...delivData]);
        XLSX.utils.book_append_sheet(wb, wsDeliv, "Entregáveis do Projeto");
    }

    XLSX.writeFile(wb, `RELATORIO_${data.title.replace(/\s+/g, '_')}.xlsx`);
};

export const exportToCSV = (data: ProcessImprovement) => {
    const rows: any[][] = [];
    rows.push(['Ordem', 'Responsavel', 'Etapa', 'Entradas', 'Cenario Atual', 'Saidas', 'Cenario Futuro']);

    data.steps.forEach((step, i) => {
        const stepInfo = [
            i + 1,
            step.role,
            step.name,
            step.inputs?.join('; ') || '',
            step.currentScenario,
            step.outputs?.join('; ') || '',
            step.noImprovement ? 'MANTER PROCESSO ATUAL' : step.futureScenario
        ];
        rows.push(stepInfo);
    });

    const csvContent = rows.map(r => r.map(cell => `"${String(cell).replace(/"/g, '""')}"`).join(",")).join("\n");
    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.setAttribute('href', url);
    link.setAttribute('download', `RELATORIO_${data.title.replace(/\s+/g, '_')}.csv`);
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
};

export const exportToPDF = (data: ProcessImprovement) => {
    const doc = new jsPDF({ orientation: 'p', unit: 'mm', format: 'a4' });

    doc.setFontSize(16);
    doc.text(data.title, 14, 20);

    doc.setFontSize(10);
    doc.text(`Setores: ${data.sectors}`, 14, 30);
    doc.text(`Gestores: ${data.managers}`, 14, 35);

    let y = 45;

    data.steps.forEach((step, i) => {
        if (y > 250) { doc.addPage(); y = 20; }

        doc.setFontSize(12);
        doc.setFont("helvetica", "bold");
        doc.text(`${i + 1}. ${step.name} (${step.role})`, 14, y);
        y += 7;

        doc.setFontSize(9);
        doc.setFont("helvetica", "bold");
        doc.text("Processo Atual:", 14, y);
        doc.setFont("helvetica", "normal");
        const splitCurrent = doc.splitTextToSize(step.currentScenario || '-', 180);
        doc.text(splitCurrent, 14, y + 5);
        y += (splitCurrent.length * 5) + 8;

        if (step.inputs && step.inputs.length > 0) {
            doc.setFont("helvetica", "bold");
            doc.text(`Entradas: ${step.inputs.join(', ')}`, 14, y);
            y += 6;
        }

        if (step.outputs && step.outputs.length > 0) {
            doc.setFont("helvetica", "bold");
            doc.text(`Saídas: ${step.outputs.join(', ')}`, 14, y);
            y += 6;
        }

        y += 5;
        doc.line(14, y, 196, y);
        y += 10;
    });

    doc.save(`PDF_${data.title.replace(/\s+/g, '_')}.pdf`);
};

export const exportToHTML = (data: ProcessImprovement) => {
    const htmlContent = `
    <html>
        <head><title>${data.title}</title></head>
        <body>
            <h1>${data.title}</h1>
            <p>Exportação HTML simplificada. Use o webapp para visualização completa.</p>
        </body>
    </html>`;

    const blob = new Blob([htmlContent], { type: 'text/html' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = `VISUALIZACAO_${data.title.replace(/\s+/g, '_')}.html`;
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
}

import React, { useState, useMemo } from 'react';
import { Deliverable, ProcessImprovement } from '../types/process';
import { EditableText } from './EditableText';
import { Button } from './ui/button';
import { Trash2, Link, X, CheckSquare } from 'lucide-react';
import { cn } from '../lib/utils';

interface DeliverableCardProps {
    deliverable: Deliverable;
    fullData: ProcessImprovement;
    onUpdate: (updated: Deliverable) => void;
    onDelete: () => void;
}

export const DeliverableCard: React.FC<DeliverableCardProps> = ({ deliverable, fullData, onUpdate, onDelete }) => {
    const [isLinking, setIsLinking] = useState(false);

    // Flatten all stories to find available ones
    const allStories = useMemo(() => {
        const stories: { storyId: string; text: string; stepName: string; userName: string; priority: string }[] = [];
        fullData.steps.forEach(step => {
            step.userCards.forEach(card => {
                card.stories.forEach(story => {
                    stories.push({
                        storyId: story.id,
                        text: story.text,
                        stepName: step.name,
                        userName: card.userName,
                        priority: story.priority
                    });
                });
            });
        });
        return stories;
    }, [fullData]);

    // Stories linked to THIS deliverable
    const linkedStories = allStories.filter(s => deliverable.linkedStoryIds.includes(s.storyId));

    const toggleStoryLink = (storyId: string) => {
        let newIds = [...deliverable.linkedStoryIds];
        if (newIds.includes(storyId)) {
            newIds = newIds.filter(id => id !== storyId);
        } else {
            newIds.push(storyId);
        }
        onUpdate({ ...deliverable, linkedStoryIds: newIds });
    };

    return (
        <div className="bg-white rounded-xl shadow-sm border border-slate-200 flex flex-col h-full min-h-[350px]">
            {/* Header */}
            <div className="p-4 border-b border-slate-100 flex items-start justify-between bg-slate-50 rounded-t-xl">
                <div className="flex-1 mr-2">
                    <label className="text-[10px] uppercase font-bold text-slate-400 block mb-1">Entregável</label>
                    <EditableText
                        value={deliverable.title}
                        onChange={(val) => onUpdate({ ...deliverable, title: val })}
                        placeholder="Título da Entrega"
                        className="font-bold text-lg text-slate-800"
                    />
                </div>
                <button onClick={onDelete} className="text-slate-300 hover:text-red-500 transition-colors">
                    <Trash2 size={16} />
                </button>
            </div>

            {/* Description */}
            <div className="p-4 border-b border-slate-100 bg-white">
                <EditableText
                    value={deliverable.description}
                    onChange={(val) => onUpdate({ ...deliverable, description: val })}
                    placeholder="O que será entregue? Qual o valor de negócio?"
                    multiline
                    className="text-sm text-slate-600 min-h-[60px]"
                />
            </div>

            {/* Linked Stories Area */}
            <div className="flex-1 p-4 bg-slate-50/50 flex flex-col">
                <div className="flex items-center justify-between mb-3">
                    <div className="flex items-center gap-2">
                        <Link size={14} className="text-slate-400" />
                        <span className="text-xs font-bold uppercase text-slate-500">Histórias Vinculadas ({linkedStories.length})</span>
                    </div>
                    <Button 
                        size="sm" 
                        variant="ghost" 
                        onClick={() => setIsLinking(!isLinking)}
                        className="h-6 text-xs text-blue-600 hover:text-blue-700 hover:bg-blue-50"
                    >
                        {isLinking ? 'Concluir Seleção' : 'Vincular Histórias'}
                    </Button>
                </div>

                <div className="flex-1 overflow-y-auto custom-scrollbar space-y-2 max-h-[300px]">
                    {isLinking ? (
                        // Selection Mode
                        <div className="space-y-2">
                             {allStories.length === 0 && <p className="text-xs text-slate-400 text-center italic py-4">Nenhuma história criada no processo.</p>}
                             {allStories.map(story => {
                                 const isSelected = deliverable.linkedStoryIds.includes(story.storyId);
                                 return (
                                     <div 
                                        key={story.storyId}
                                        onClick={() => toggleStoryLink(story.storyId)}
                                        className={cn(
                                            "p-2 rounded border text-xs cursor-pointer transition-all hover:shadow-sm flex items-start gap-2",
                                            isSelected ? "bg-blue-50 border-blue-200" : "bg-white border-slate-200 hover:border-blue-300"
                                        )}
                                     >
                                        <div className={cn(
                                            "w-4 h-4 rounded border flex items-center justify-center shrink-0 mt-0.5 transition-colors",
                                            isSelected ? "bg-blue-600 border-blue-600 text-white" : "bg-white border-slate-300"
                                        )}>
                                            {isSelected && <CheckSquare size={10} />}
                                        </div>
                                        <div className="flex-1">
                                            <p className={cn("leading-tight font-medium", isSelected ? "text-blue-900" : "text-slate-700")}>{story.text}</p>
                                            <div className="flex items-center gap-2 mt-1 opacity-70">
                                                <span className="text-[10px] bg-slate-100 px-1 rounded">{story.stepName}</span>
                                                <span className="text-[10px] bg-slate-100 px-1 rounded">{story.userName}</span>
                                                <span className={cn(
                                                    "text-[10px] px-1 rounded font-bold uppercase", 
                                                    story.priority === 'Essencial' ? "text-red-600 bg-red-50" : "text-slate-500 bg-slate-100"
                                                )}>{story.priority}</span>
                                            </div>
                                        </div>
                                     </div>
                                 )
                             })}
                        </div>
                    ) : (
                        // View Mode
                        <>
                            {linkedStories.length === 0 ? (
                                <div className="text-center py-8 text-slate-400 text-xs italic border-2 border-dashed border-slate-200 rounded-lg">
                                    Nenhuma história vinculada a este entregável.
                                </div>
                            ) : (
                                linkedStories.map(story => (
                                    <div key={story.storyId} className="bg-white p-2 rounded border border-slate-200 text-xs shadow-sm group relative">
                                        <p className="text-slate-700 font-medium mb-1 pr-4">{story.text}</p>
                                        <div className="flex flex-wrap gap-1">
                                            <span className="text-[9px] bg-slate-100 text-slate-500 px-1 rounded border border-slate-100">{story.stepName}</span>
                                            <span className="text-[9px] bg-slate-100 text-slate-500 px-1 rounded border border-slate-100">{story.userName}</span>
                                        </div>
                                        <button 
                                            onClick={() => toggleStoryLink(story.storyId)}
                                            className="absolute top-2 right-2 text-slate-300 hover:text-red-500 opacity-0 group-hover:opacity-100 transition-opacity"
                                            title="Desvincular"
                                        >
                                            <X size={12} />
                                        </button>
                                    </div>
                                ))
                            )}
                        </>
                    )}
                </div>
            </div>
        </div>
