    const risks = data.risks || [];

    const addRule = () => {
        if (newRule.trim()) {
            onUpdate('processRules', [...rules, newRule.trim()]);
            setNewRule('');
        }
    };

    const removeRule = (idx: number) => {
        onUpdate('processRules', rules.filter((_, i) => i !== idx));
    };

    const addRisk = () => {
        if (newRisk.trim()) {
            onUpdate('risks', [...risks, newRisk.trim()]);
            setNewRisk('');
        }
    };

    const removeRisk = (idx: number) => {
        onUpdate('risks', risks.filter((_, i) => i !== idx));
    };

    return (
        <div className={cn(
            "h-full border-r border-slate-200 bg-white shadow-sm transition-all duration-300 ease-in-out relative shrink-0 z-20",
            isOpen ? "w-80" : "w-12"
        )}>
            {/* Toggle Button - Absolute to overlap border */}
            <button
                onClick={onToggle}
                className="absolute -right-3 top-24 w-6 h-6 bg-white border border-slate-200 rounded-full flex items-center justify-center text-slate-500 shadow-sm hover:text-blue-600 hover:border-blue-300 z-50 focus:outline-none"
                title={isOpen ? "Fechar painel lateral" : "Abrir Regras e Riscos"}
            >
                {isOpen ? <ChevronLeft size={14} /> : <ChevronRight size={14} />}
            </button>

            {/* Content Container - overflow hidden to clip the inner w-80 content when collapsed */}
            <div className="h-full w-full overflow-hidden relative">

                {/* OPEN STATE CONTENT */}
                <div className={cn(
                    "flex-1 overflow-y-auto custom-scrollbar flex flex-col w-80 h-full transition-opacity duration-300 absolute top-0 left-0 bg-white",
                    isOpen ? "opacity-100 visible" : "opacity-0 invisible pointer-events-none"
                )}>
                    {/* Header */}
                    <div className="p-4 bg-slate-50 border-b border-slate-100 shrink-0">
                        <h3 className="font-bold text-slate-700 text-sm uppercase tracking-wide">Contexto do Processo</h3>
                    </div>

                    <div className="p-4 space-y-6 flex-1 overflow-y-auto custom-scrollbar">
                        {/* RULES SECTION */}
                        <div className="space-y-3">
                            <div className="flex items-center gap-2 text-slate-800 font-bold text-sm">
                                <Scale className="w-4 h-4 text-indigo-600" />
                                Regras de Negócio
                            </div>

                            <div className="space-y-2">
                                {rules.length === 0 && <p className="text-xs text-slate-400 italic">Nenhuma regra definida.</p>}
                                {rules.map((rule, idx) => (
                                    <div key={idx} className="group p-3 bg-indigo-50/50 border border-indigo-100 rounded-lg text-xs text-slate-700 shadow-sm relative hover:border-indigo-200 transition-colors">
                                        <p className="pr-4 leading-relaxed">{rule}</p>
                                        <button 
                                            onClick={() => removeRule(idx)}
                                            className="absolute top-2 right-2 text-slate-300 hover:text-red-500 opacity-0 group-hover:opacity-100 transition-opacity"
                                        >
                                            <Trash2 size={12} />
                                        </button>
                                    </div>
                                ))}
                            </div>

                            <div className="flex gap-1 pt-1">
                                <Input 
                                    value={newRule}
                                    onChange={(e) => setNewRule(e.target.value)}
                                    onKeyDown={(e) => e.key === 'Enter' && addRule()}
                                    placeholder="Nova regra..."
                                    className="h-8 text-xs bg-white"
                                />
                                <Button size="icon" onClick={addRule} className="h-8 w-8 shrink-0 bg-slate-800 hover:bg-slate-700">
                                    <Plus size={14} />
                                </Button>
                            </div>
                        </div>

                        <div className="w-full border-t border-slate-100"></div>

                        {/* RISKS SECTION */}
                        <div className="space-y-3">
                            <div className="flex items-center gap-2 text-slate-800 font-bold text-sm">
                                <ShieldAlert className="w-4 h-4 text-amber-500" />
                                Riscos Detectados
                            </div>

                            <div className="space-y-2">
                                {risks.length === 0 && <p className="text-xs text-slate-400 italic">Nenhum risco mapeado.</p>}
                                {risks.map((risk, idx) => (
                                    <div key={idx} className="group p-3 bg-amber-50/50 border border-amber-100 rounded-lg text-xs text-slate-700 shadow-sm relative hover:border-amber-200 transition-colors">
                                        <p className="pr-4 leading-relaxed">{risk}</p>
                                        <button 
                                            onClick={() => removeRisk(idx)}
                                            className="absolute top-2 right-2 text-slate-300 hover:text-red-500 opacity-0 group-hover:opacity-100 transition-opacity"
                                        >
                                            <Trash2 size={12} />
                                        </button>
                                    </div>
                                ))}
                            </div>

                            <div className="flex gap-1 pt-1">
                                <Input 
                                    value={newRisk}
                                    onChange={(e) => setNewRisk(e.target.value)}
                                    onKeyDown={(e) => e.key === 'Enter' && addRisk()}
                                    placeholder="Novo risco..."
                                    className="h-8 text-xs bg-white"
                                />
                                <Button size="icon" onClick={addRisk} className="h-8 w-8 shrink-0 bg-slate-800 hover:bg-slate-700">
                                    <Plus size={14} />
                                </Button>
                            </div>
                        </div>
                    </div>
                </div>

                {/* CLOSED STATE CONTENT */}
                <div 
                    onClick={onToggle}
                    className={cn(
                        "absolute inset-0 flex flex-col items-center pt-32 cursor-pointer hover:bg-slate-50 transition-all duration-300 gap-6",
                        !isOpen ? "opacity-100 visible" : "opacity-0 invisible pointer-events-none"
                    )}
                >
                    <div className="transform -rotate-90 whitespace-nowrap text-[10px] font-bold text-slate-400 uppercase tracking-widest flex items-center gap-2 mt-4">
                        REGRAS E RISCOS
                    </div>
                </div>

            </div>
        </div>
    );
};

import React, { useState } from 'react';
import { ProcessStep, UserCard, MappingNote } from '../types/process';
import { EditableText } from './EditableText';
import { UserStoryCard } from './UserStoryCard';
import { MappingCard } from './MappingCard';
import { Button } from './ui/button';
import { Plus, Layout, Users, ArrowRight, Lightbulb, FileInput, FileOutput, X, FileText, UserCircle2, Hash, NotebookPen } from 'lucide-react';
import { generateId, cn } from '../lib/utils';
import { Input } from './ui/input';

interface StepDetailsProps {
  step: ProcessStep;
  onUpdate: (updatedStep: ProcessStep) => void;
}

// Componente auxiliar para lista de Entradas/Saídas
const ListEditor: React.FC<{
    items: string[];
    onChange: (items: string[]) => void;
    placeholder: string;
    icon?: React.ReactNode;
    colorClass?: string;
    title: string;
    headerIcon: React.ReactNode;
}> = ({ items = [], onChange, placeholder, icon, colorClass = "text-slate-600", title, headerIcon }) => {
    const [newItem, setNewItem] = useState("");

    const handleAdd = () => {
        if (newItem.trim()) {
            onChange([...items, newItem.trim()]);
            setNewItem("");
        }
    };

    const handleKeyDown = (e: React.KeyboardEvent) => {
        if (e.key === 'Enter') handleAdd();
    };

    const handleRemove = (index: number) => {
        onChange(items.filter((_, i) => i !== index));
    };

    return (
        <div className="flex flex-col h-full min-h-0">
            <div className="flex items-center gap-2 pb-3 mb-2 border-b border-slate-200">
                {headerIcon}
                <span className="text-xs font-bold uppercase text-slate-600">{title}</span>
                <span className="bg-slate-200 text-slate-600 text-[9px] px-1.5 rounded-full">{items.length}</span>
            </div>

            <div className="flex-1 overflow-y-auto space-y-2 pr-1 custom-scrollbar">
                {items.length === 0 && (
                    <div className="text-center text-[10px] text-slate-400 italic py-2">
                        Nenhum item.
                    </div>
                )}
                {items.map((item, idx) => (
                    <div key={idx} className="group flex items-start gap-2 text-xs bg-white p-2 rounded border border-slate-200 shadow-sm hover:border-blue-300 transition-colors">
                        <div className={cn("mt-0.5 shrink-0", colorClass)}>{icon}</div>
                        <span className="flex-1 text-slate-700 leading-tight break-words">{item}</span>
                        <button 
                            onClick={() => handleRemove(idx)}
                            className="text-slate-300 hover:text-red-500 opacity-0 group-hover:opacity-100 transition-opacity"
                        >
                            <X size={12} />
                        </button>
                    </div>
                ))}
            </div>

            <div className="mt-2 flex gap-1 pt-2 border-t border-slate-100">
                <Input 
                    value={newItem}
                    onChange={(e) => setNewItem(e.target.value)}
                    onKeyDown={handleKeyDown}
                    placeholder={placeholder}
                    className="h-7 text-xs bg-white"
                />
                <Button onClick={handleAdd} size="icon" className="h-7 w-7 bg-slate-200 hover:bg-slate-300 text-slate-600">
                    <Plus size={12} />
                </Button>
            </div>
        </div>
    );
}

export const StepDetails: React.FC<StepDetailsProps> = ({ step, onUpdate }) => {
  const [activeTab, setActiveTab] = useState<'overview' | 'scenarios' | 'stories' | 'mappings'>('overview');

  const addUserCard = () => {
    const newCard: UserCard = {
      id: generateId(),
      userName: '',
      stories: []
    };
    onUpdate({ ...step, userCards: [...step.userCards, newCard] });
    setActiveTab('stories');
  };

  const updateUserCard = (index: number, updatedCard: UserCard) => {
      const newCards = [...step.userCards];
      newCards[index] = updatedCard;
      onUpdate({ ...step, userCards: newCards });
  };

  const deleteUserCard = (index: number) => {
      if(confirm("Remover usuário?")) {
          const newCards = step.userCards.filter((_, i) => i !== index);
          onUpdate({ ...step, userCards: newCards });
      }
  };

  const addMapping = () => {
      const newMapping: MappingNote = {
          id: generateId(),
          interviewee: '',
          date: new Date().toISOString().split('T')[0],
          notes: ''
      };
      const currentMappings = step.mappings || [];
      onUpdate({ ...step, mappings: [...currentMappings, newMapping] });
  };

  const updateMapping = (index: number, updatedMapping: MappingNote) => {
      const currentMappings = step.mappings || [];
      const newMappings = [...currentMappings];
      newMappings[index] = updatedMapping;
      onUpdate({ ...step, mappings: newMappings });
  };

  const deleteMapping = (index: number) => {
      if(confirm("Excluir este mapeamento?")) {
          const currentMappings = step.mappings || [];
          const newMappings = currentMappings.filter((_, i) => i !== index);
          onUpdate({ ...step, mappings: newMappings });
