    const storiesHeader = ['Etapa Relacionada', 'Usuário/Papel', 'Prioridade', 'História (Requisito)'];
    const storiesData: any[] = [];
    data.steps.forEach(step => {
        step.userCards.forEach(card => {
            card.stories.forEach(story => {
                storiesData.push([
                    step.name || 'Etapa sem nome',
                    card.userName || 'Não especificado',
                    story.priority,
                    story.text
                ]);
            });
        });
    });
    const wsStories = XLSX.utils.aoa_to_sheet([storiesHeader, ...storiesData]);
    XLSX.utils.book_append_sheet(wb, wsStories, "Requisitos Detalhados");

    // Aba 5: Entregáveis (Novo)
    if (data.deliverables && data.deliverables.length > 0) {
        const delivHeader = ['Entregável', 'Descrição', 'Qtd Histórias'];
        const delivData = data.deliverables.map(d => [
            d.title,
            d.description,
            d.linkedStoryIds.length
        ]);
        const wsDeliv = XLSX.utils.aoa_to_sheet([delivHeader, ...delivData]);
        XLSX.utils.book_append_sheet(wb, wsDeliv, "Entregáveis do Projeto");
    }

    XLSX.writeFile(wb, `RELATORIO_${data.title.replace(/\s+/g, '_')}.xlsx`);
};

export const exportToCSV = (data: ProcessImprovement) => {
    const rows: any[][] = [];
    rows.push(['Ordem', 'Responsavel', 'Etapa', 'Entradas', 'Cenario Atual', 'Saidas', 'Cenario Futuro']);

    data.steps.forEach((step, i) => {
        const stepInfo = [
            i + 1,
            step.role,
            step.name,
            step.inputs?.join('; ') || '',
            step.currentScenario,
            step.outputs?.join('; ') || '',
            step.noImprovement ? 'MANTER PROCESSO ATUAL' : step.futureScenario
        ];
        rows.push(stepInfo);
    });

    const csvContent = rows.map(r => r.map(cell => `"${String(cell).replace(/"/g, '""')}"`).join(",")).join("\n");
    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.setAttribute('href', url);
    link.setAttribute('download', `RELATORIO_${data.title.replace(/\s+/g, '_')}.csv`);
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
};

export const exportToPDF = (data: ProcessImprovement, type: 'simple' | 'complete' = 'simple') => {
    const doc = new jsPDF({ orientation: 'p', unit: 'mm', format: 'a4' });
    const margin = 14;
    const pageWidth = 210;
    const maxLineWidth = pageWidth - (margin * 2);
    let y = 20;

    const checkPageBreak = (heightNeeded: number) => {
        if (y + heightNeeded > 280) {
            doc.addPage();
            y = 20;
            return true;
        }
        return false;
    };

    // Header do Documento
    doc.setFontSize(16);
    doc.setFont("helvetica", "bold");
    doc.text(data.title.toUpperCase(), margin, y);
    y += 8;

    doc.setFontSize(10);
    doc.setFont("helvetica", "normal");
    doc.text(`Setores: ${data.sectors}`, margin, y);
    y += 5;
    doc.text(`Gestores: ${data.managers}`, margin, y);
    y += 5;

    // Tipo de Relatório
    doc.setFontSize(8);
    doc.setTextColor(100);
    doc.text(`Relatório: ${type === 'complete' ? 'Completo (Detalhado)' : 'Resumido (Cenários e Histórias)'} | Gerado em: ${new Date().toLocaleDateString()}`, margin, y);
    doc.setTextColor(0);
    y += 10;

    doc.setLineWidth(0.5);
    doc.line(margin, y, pageWidth - margin, y);
    y += 10;

    // Loop Etapas
    data.steps.forEach((step, i) => {
        checkPageBreak(50); // Check inicial generoso para cabeçalho da etapa

        // Etapa Header
        doc.setFontSize(14);
        doc.setFont("helvetica", "bold");
        doc.setFillColor(240, 240, 240);
        doc.rect(margin, y - 6, maxLineWidth, 10, 'F');
        doc.text(`${i + 1}. ${step.name}`, margin + 2, y);

        // Responsável
        doc.setFontSize(10);
        doc.setFont("helvetica", "italic");
        doc.setTextColor(80);
        const roleText = step.role ? `Responsável: ${step.role}` : 'Responsável não definido';
        const roleWidth = doc.getTextWidth(roleText);
        doc.text(roleText, pageWidth - margin - roleWidth - 2, y);
        doc.setTextColor(0);

        y += 10;

        // Entradas e Saídas (Apenas modo Complete)
        if (type === 'complete') {
            doc.setFontSize(9);
            if (step.inputs && step.inputs.length > 0) {
                checkPageBreak(15);
                doc.setFont("helvetica", "bold");
                doc.setTextColor(22, 163, 74); // Green
                doc.text("Entradas:", margin, y);
                doc.setFont("helvetica", "normal");
                doc.setTextColor(0);
                const inputsText = step.inputs.join(', ');
                const splitInputs = doc.splitTextToSize(inputsText, maxLineWidth - 20);
                doc.text(splitInputs, margin + 20, y);
                y += (splitInputs.length * 4) + 2;
            }

            if (step.outputs && step.outputs.length > 0) {
                checkPageBreak(15);
                doc.setFont("helvetica", "bold");
                doc.setTextColor(37, 99, 235); // Blue
                doc.text("Saídas:", margin, y);
                doc.setFont("helvetica", "normal");
                doc.setTextColor(0);
                const outputsText = step.outputs.join(', ');
                const splitOutputs = doc.splitTextToSize(outputsText, maxLineWidth - 20);
                doc.text(splitOutputs, margin + 20, y);
                y += (splitOutputs.length * 4) + 2;
            }

            if ((step.inputs?.length || 0) > 0 || (step.outputs?.length || 0) > 0) {
                y += 4; // Spacer extra se houve inputs/outputs
            }
        }

        // Cenário Atual (AS-IS)
        checkPageBreak(20);
        doc.setFontSize(10);
        doc.setFont("helvetica", "bold");
        doc.text("Como é Hoje (AS-IS):", margin, y);
        y += 5;
        doc.setFont("helvetica", "normal");
        const asIsText = step.currentScenario || '-';
        const splitAsIs = doc.splitTextToSize(asIsText, maxLineWidth);
        checkPageBreak(splitAsIs.length * 5);
        doc.text(splitAsIs, margin, y);
        y += (splitAsIs.length * 5) + 6;

        // Cenário Futuro (TO-BE)
        checkPageBreak(20);
        doc.setFont("helvetica", "bold");
        doc.text("Como Será (TO-BE):", margin, y);
        y += 5;
        doc.setFont("helvetica", "normal");

        let toBeText = step.futureScenario || '-';
        if (step.noImprovement) toBeText = "MANTER O PROCESSO ATUAL (SEM MELHORIAS).";

        const splitToBe = doc.splitTextToSize(toBeText, maxLineWidth);
        checkPageBreak(splitToBe.length * 5);
        doc.text(splitToBe, margin, y);
        y += (splitToBe.length * 5) + 8;

        // Histórias de Usuário (AGRUPADAS) - Layout melhorado com caixas separadoras
        if (step.userCards && step.userCards.length > 0) {
            checkPageBreak(20);

            // Título Geral da Seção
            doc.setFontSize(11);
            doc.setFont("helvetica", "bold");
            doc.setTextColor(0, 0, 0);
            doc.text("Histórias de Usuário:", margin, y);
            y += 6;

            step.userCards.forEach(card => {
                const userName = card.userName || 'Participante não identificado';

                checkPageBreak(30); // Garante que o cabeçalho e pelo menos uma história caibam

                // Caixa do Usuário (Separador)
                doc.setFillColor(248, 250, 252); // Slate-50 bem claro
                doc.setDrawColor(226, 232, 240); // Slate-200
                doc.rect(margin + 2, y, maxLineWidth - 4, 8, 'FD'); // Filled and Stroked

                // Nome do Usuário
                doc.setFontSize(10);
                doc.setFont("helvetica", "bold");
                doc.setTextColor(15, 95, 135); // Brand Blue color
                doc.text(`Participante: ${userName}`, margin + 5, y + 5.5);
                doc.setTextColor(0);
                y += 12;

                if (card.stories.length === 0) {
                     doc.setFont("helvetica", "italic");
                     doc.setFontSize(9);
                     doc.setTextColor(150);
                     doc.text("(Nenhuma história definida para este usuário)", margin + 8, y);
                     doc.setTextColor(0);
                     y += 6;
                } else {
                    card.stories.forEach(story => {
                        const content = story.text;
                        const priorityLabel = story.priority;

                        // Icone bullet estilizado
                        const bulletX = margin + 6;

                        doc.setFontSize(8);
                        doc.setFont("helvetica", "bold");

                        // Cor da prioridade
                        if (priorityLabel === 'Essencial') doc.setTextColor(220, 38, 38); // Red
                        else if (priorityLabel === 'Deveria ter') doc.setTextColor(202, 138, 4); // Yellow/Gold
                        else doc.setTextColor(100); // Slate

                        doc.text(`[${priorityLabel}]`, bulletX, y);

                        // Texto da história
                        doc.setTextColor(0);
                        doc.setFontSize(9);
                        doc.setFont("helvetica", "normal");

                        // Cálculo de largura considerando o prefixo da prioridade
                        const prefixWidth = doc.getTextWidth(`[${priorityLabel}] `);
                        const splitStory = doc.splitTextToSize(content, maxLineWidth - 25);

                        checkPageBreak(splitStory.length * 5);

                        doc.text(splitStory, bulletX + prefixWidth + 2, y);
                        y += (splitStory.length * 4.5) + 3;
                    });
                }
                y += 2; // Espaço extra após cada bloco de usuário
            });
            y += 4;
        }

        // Separador de Etapa
        y += 5;
        doc.setDrawColor(200);
        doc.line(margin, y, pageWidth - margin, y);
        doc.setDrawColor(0);
        y += 10;
    });

    // Adiciona numeração de páginas
    const pageCount = (doc as any).internal.getNumberOfPages();
    for (let i = 1; i <= pageCount; i++) {
        doc.setPage(i);
        doc.setFontSize(8);
        doc.text(`Página ${i} de ${pageCount}`, pageWidth / 2, 290, { align: 'center' });
    }

    doc.save(`PDF_${type.toUpperCase()}_${data.title.replace(/\s+/g, '_')}.pdf`);
};

export const exportToHTML = (data: ProcessImprovement) => {
    const htmlContent = `
    <html>
        <head><title>${data.title}</title></head>
        <body>
            <h1>${data.title}</h1>
            <p>Exportação HTML simplificada. Use o webapp para visualização completa.</p>
        </body>
    </html>`;

    const blob = new Blob([htmlContent], { type: 'text/html' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = `VISUALIZACAO_${data.title.replace(/\s+/g, '_')}.html`;
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
}

import React from 'react';
import { ProcessStep } from '../types/process';
import { EditableText } from './EditableText';
import { GripVertical, Plus, Trash2, Settings2, Play, Flag } from 'lucide-react';
import { cn } from '../lib/utils';
import {
  DndContext, 
  closestCenter,
  KeyboardSensor,
  PointerSensor,
  useSensor,
  useSensors,
  DragEndEvent
} from '@dnd-kit/core';
import {
  arrayMove,
  SortableContext,
  sortableKeyboardCoordinates,
  horizontalListSortingStrategy,
  useSortable
} from '@dnd-kit/sortable';
import { CSS } from '@dnd-kit/utilities';

interface TimelineProps {
  steps: ProcessStep[];
  selectedStepId: string | null;
  onSelectStep: (id: string) => void;
  onUpdateSteps: (steps: ProcessStep[]) => void;
  onAddStep: () => void;
  onDeleteStep: (id: string) => void;
}

interface SortableStepProps {
  step: ProcessStep;
  index: number;
  isSelected: boolean;
  onSelect: () => void;
  onUpdate: (val: string, field: 'name' | 'role') => void;
  onDelete: () => void;
}

const SortableStep: React.FC<SortableStepProps> = ({ step, index, isSelected, onSelect, onUpdate, onDelete }) => {
    const {
        attributes,
        listeners,
        setNodeRef,
        transform,
        transition,
        isDragging
    } = useSortable({ id: step.id });

    const style = {
        transform: CSS.Transform.toString(transform),
        transition,
        zIndex: isDragging ? 50 : 'auto',
    };

    return (
        <div 
            ref={setNodeRef} 
            style={style}
            className="flex flex-col items-center justify-start h-full min-w-[200px] max-w-[200px] group relative pt-4"
        >
            {/* Card Superior (Role + Name) */}
            <div 
                onClick={onSelect}
                className={cn(
                    "w-[90%] h-24 p-3 rounded-xl border-2 transition-all duration-200 cursor-pointer flex flex-col gap-1 relative bg-white shadow-sm hover:shadow-md",
                    isSelected 
                        ? "border-blue-600 ring-4 ring-blue-50 -translate-y-1 z-10" 
                        : "border-slate-200 hover:border-blue-300"
                )}
            >
                {/* Drag Handle & Delete (Hover only) */}
                <div className="absolute -top-3 right-0 left-0 flex justify-center opacity-0 group-hover:opacity-100 transition-opacity gap-1 z-20">
                    <button {...attributes} {...listeners} className="bg-slate-800 text-white p-1 rounded cursor-grab active:cursor-grabbing shadow-sm hover:bg-slate-700">
                        <GripVertical size={12} />
                    </button>
                    <button 
                        onPointerDown={(e) => e.stopPropagation()} 
                        onClick={(e) => { 
                            e.stopPropagation(); 
                            onDelete(); 
                        }} 
                        className="bg-red-100 text-red-600 p-1 rounded hover:bg-red-200 shadow-sm border border-red-200 transition-colors"
                        title="Remover Etapa"
                    >
                        <Trash2 size={12} />
                    </button>
                </div>

                {/* Conteúdo do Card */}
                <div className="flex flex-col h-full overflow-hidden">
                    <div className="mb-1 shrink-0">
                        <EditableText
                            value={step.role}
                            onChange={(val) => onUpdate(val, 'role')}
                            placeholder="DEFINIR PAPEL/SETOR"
                            className="text-[10px] font-bold uppercase text-slate-500 bg-slate-50 px-1 rounded w-full text-center"
                        />
                    </div>
                    <div className="flex-1 flex items-center justify-center text-center">
                        <EditableText
                            value={step.name}
                            onChange={(val) => onUpdate(val, 'name')}
                            placeholder="Nome da Etapa"
                            className={cn(
                                "text-xs font-bold leading-tight w-full text-center",
                                isSelected ? "text-blue-900" : "text-slate-700"
                            )}
                        />
                    </div>
                </div>

                {/* Seta indicativa se selecionado */}
                {isSelected && (
                    <div className="absolute left-1/2 -bottom-2.5 -translate-x-1/2 w-0 h-0 border-l-[8px] border-l-transparent border-r-[8px] border-r-transparent border-t-[8px] border-t-blue-600"></div>
                )}
            </div>

            {/* Linha e Conector */}
            <div className="h-12 w-full flex flex-col items-center justify-center relative shrink-0">
                <div className={cn(
                    "w-full h-1 absolute top-1/2 -translate-y-1/2",
                    isSelected ? "bg-blue-200" : "bg-slate-200"
                )}></div>
                <div className={cn(
                    "w-6 h-6 rounded-full border-4 z-10 flex items-center justify-center text-[10px] font-bold transition-all",
                    isSelected 
                        ? "bg-blue-600 border-white ring-2 ring-blue-200 text-white scale-110" 
                        : "bg-white border-slate-300 text-slate-400"
                )}>
                    {index + 1}
                </div>
            </div>
        </div>
    );
}

const StartNode: React.FC<{ isSelected: boolean; onSelect: () => void }> = ({ isSelected, onSelect }) => (
    <div className="flex flex-col items-center justify-end h-full min-w-[100px] pb-[13px] relative z-10">
        <button 
            onClick={onSelect}
            className={cn(
                "w-12 h-12 rounded-full flex items-center justify-center shadow-lg transition-all duration-200 border-4 relative",
                isSelected 
                    ? "bg-green-600 border-green-200 text-white scale-110 ring-2 ring-green-100" 
                    : "bg-green-500 border-white text-white hover:bg-green-600"
            )}
            title="Início do Processo"
        >
            <Play size={20} fill="currentColor" className="ml-0.5" />
        </button>
        {/* Connector Line (Right only) */}
        <div className="absolute right-0 bottom-[35px] w-1/2 h-1 bg-slate-200 -z-10"></div>
    </div>
);

const EndNode: React.FC<{ isSelected: boolean; onSelect: () => void }> = ({ isSelected, onSelect }) => (
    <div className="flex flex-col items-center justify-end h-full min-w-[100px] pb-[13px] relative z-10">
        <button 
            onClick={onSelect}
            className={cn(
                "w-12 h-12 rounded-full flex items-center justify-center shadow-lg transition-all duration-200 border-4 relative",
                isSelected 
                    ? "bg-red-600 border-red-200 text-white scale-110 ring-2 ring-red-100" 
                    : "bg-red-500 border-white text-white hover:bg-red-600"
            )}
            title="Fim do Processo"
        >
            <Flag size={20} fill="currentColor" />
        </button>
        {/* Connector Line (Left only) */}
        <div className="absolute left-0 bottom-[35px] w-1/2 h-1 bg-slate-200 -z-10"></div>
    </div>
);

export const Timeline: React.FC<TimelineProps> = ({ steps, selectedStepId, onSelectStep, onUpdateSteps, onAddStep, onDeleteStep }) => {

    const sensors = useSensors(
        useSensor(PointerSensor, { activationConstraint: { distance: 5 } }),
        useSensor(KeyboardSensor, { coordinateGetter: sortableKeyboardCoordinates })
    );

    const handleDragEnd = (event: DragEndEvent) => {
        const { active, over } = event;
        if (over && active.id !== over.id) {
            const oldIndex = steps.findIndex((s) => s.id === active.id);
            const newIndex = steps.findIndex((s) => s.id === over.id);
            onUpdateSteps(arrayMove(steps, oldIndex, newIndex));
        }
    };

    const handleUpdateStep = (id: string, val: string, field: 'name' | 'role') => {
        const newSteps = steps.map(s => s.id === id ? { ...s, [field]: val } : s);
        onUpdateSteps(newSteps);
    };

    return (
        <div className="flex-shrink-0 bg-white border-b border-slate-200 h-[220px] relative flex flex-col">
            <div className="absolute top-0 left-0 bg-slate-50 px-3 py-1 rounded-br-lg text-[10px] font-bold text-slate-400 border-b border-r border-slate-200 z-20 flex items-center gap-1">
                <Settings2 size={12} /> TIMELINE DO PROCESSO
            </div>

            <div className="flex-1 overflow-x-auto custom-scrollbar flex px-8 relative">
                {/* Wrapper to center content if needed */}
                <div className="flex items-start h-full pt-8 pb-4 min-w-max mx-auto">

                    <StartNode isSelected={selectedStepId === 'START'} onSelect={() => onSelectStep('START')} />

                    <DndContext sensors={sensors} collisionDetection={closestCenter} onDragEnd={handleDragEnd}>
                        <SortableContext items={steps.map(s => s.id)} strategy={horizontalListSortingStrategy}>
                            {steps.map((step, index) => (
                                <SortableStep
                                    key={step.id}
                                    step={step}
                                    index={index}
                                    isSelected={selectedStepId === step.id}
                                    onSelect={() => onSelectStep(step.id)}
                                    onUpdate={(val, field) => handleUpdateStep(step.id, val, field)}
                                    onDelete={() => onDeleteStep(step.id)}
                                />
                            ))}
                        </SortableContext>
                    </DndContext>

                    {/* Add Button */}
                    <div className="h-full flex items-center justify-center pl-4 pr-4 min-w-[100px] relative">
                         {/* Line pass through */}
                         <div className="absolute left-0 right-0 bottom-[35px] h-1 bg-slate-200"></div>
                        <button 
                            onClick={onAddStep}
                            className="group flex flex-col items-center gap-2 text-slate-300 hover:text-blue-600 transition-colors z-10 bg-white"
                        >
                            <div className="w-10 h-10 rounded-full border-2 border-dashed border-current flex items-center justify-center group-hover:bg-blue-50">
                                <Plus size={20} />
                            </div>
                            <span className="text-xs font-bold uppercase">Adicionar</span>
                        </button>
                    </div>

                    <EndNode isSelected={selectedStepId === 'END'} onSelect={() => onSelectStep('END')} />
                </div>
            </div>
        </div>
    );
};

import React from 'react';
import { ProcessNode, SimpleCard } from '../types/process';
import { EditableText } from './EditableText';
import { Button } from './ui/button';
import { Plus, Trash2, Play, Flag, ListTodo } from 'lucide-react';
import { generateId, cn } from '../lib/utils';

interface NodeDetailsProps {
  node: ProcessNode;
  type: 'start' | 'end';
  onUpdate: (updatedNode: ProcessNode) => void;
}

export const NodeDetails: React.FC<NodeDetailsProps> = ({ node, type, onUpdate }) => {

  const addCard = () => {
    const newCard: SimpleCard = {
      id: generateId(),
      title: '',
      text: ''
    };
    onUpdate({ ...node, cards: [...node.cards, newCard] });
  };

  const updateCard = (id: string, field: 'title' | 'text', value: string) => {
    const newCards = node.cards.map(c => 
      c.id === id ? { ...c, [field]: value } : c
    );
    onUpdate({ ...node, cards: newCards });
  };

  const deleteCard = (id: string) => {
    if (confirm('Excluir este card?')) {
      const newCards = node.cards.filter(c => c.id !== id);
      onUpdate({ ...node, cards: newCards });
    }
  };

  const isStart = type === 'start';
  const tabTitle = isStart ? 'Pré-Operacional' : 'Pós-Operacional';
  const colorClass = isStart ? 'text-green-600' : 'text-red-600';
  const bgClass = isStart ? 'bg-green-50' : 'bg-red-50';
  const borderClass = isStart ? 'border-green-200' : 'border-red-200';

  return (
    <div className="flex-1 flex flex-col min-h-0 bg-slate-50">
      {/* Tabs Bar */}
      <div className="bg-white border-b border-slate-200 px-6 flex items-center gap-6 shadow-sm z-10">
        <button
            className={cn(
                "py-4 text-sm font-bold border-b-2 flex items-center gap-2 transition-colors",
                isStart ? "border-green-600 text-green-700" : "border-red-600 text-red-700"
            )}
        >
            {isStart ? <Play size={16} /> : <Flag size={16} />}
            {tabTitle}
            <span className="bg-slate-100 text-slate-600 px-1.5 py-0.5 rounded-full text-[10px]">
                {node.cards.length}
            </span>
        </button>
      </div>

      {/* Content Area */}
      <div className="flex-1 overflow-y-auto p-8 custom-scrollbar">
        <div className="max-w-[1200px] mx-auto">

             <div className="flex items-center justify-between mb-6">
                 <div>
                    <h2 className={cn("text-xl font-bold flex items-center gap-2", colorClass)}>
                        {isStart ? "Premissas e Entradas Iniciais" : "Entregas Finais e Conclusão"}
                    </h2>
                    <p className="text-slate-500 text-sm mt-1">
                        {isStart 
                            ? "Defina o que é necessário antes do processo começar (gatilhos, regras iniciais, premissas)." 
                            : "Defina o que é gerado ao final de todo o fluxo (resultados, entregas finais, KPIs)."}
                    </p>
                 </div>
                 <Button onClick={addCard} className={cn("text-white shadow-sm", isStart ? "bg-green-600 hover:bg-green-700" : "bg-red-600 hover:bg-red-700")}>
                    <Plus className="w-4 h-4 mr-2" />
                    Adicionar Item
                 </Button>
             </div>

             {node.cards.length === 0 ? (
                 <div className="bg-white border-2 border-dashed border-slate-200 rounded-xl p-12 text-center flex flex-col items-center justify-center">
                    <div className={cn("p-4 rounded-full mb-4", bgClass)}>
                        <ListTodo className={cn("w-8 h-8", colorClass)} />
                    </div>
                    <h4 className="text-slate-600 font-medium mb-1">Nenhum item registrado</h4>
                    <p className="text-slate-400 text-sm mb-4">
