                    placeholder="Descreva este item com mais detalhes. Quais são as especificações? Quais são as regras aplicáveis?"
                    multiline
                    className="flex-1 text-sm leading-relaxed text-slate-700 min-h-[150px]"
                />
             </div>
        </div>
    </div>
  );
};

import React from 'react';
import { ProcessImprovement, DeipItem, DeipCategory } from '../types/process';
import { Timeline } from './Timeline';
import { DeipCard } from './DeipCard';
import { Plus, Shield, ArrowRightFromLine, ArrowLeftFromLine, Hammer } from 'lucide-react';
import { generateId, cn } from '../lib/utils';
import { Button } from './ui/button';

interface DeipLayoutProps {
  data: ProcessImprovement;
  selectedId: string | null;
  onSelect: (id: string, type: 'step' | 'deip' | 'start' | 'end') => void;
  onUpdateDeipItems: (items: DeipItem[]) => void;
  // Timeline props passed through
  onUpdateSteps: (steps: any[]) => void;
  onAddStep: () => void;
  onDeleteStep: (id: string) => void;
}

export const DeipLayout: React.FC<DeipLayoutProps> = ({
  data,
  selectedId,
  onSelect,
  onUpdateDeipItems,
  onUpdateSteps,
  onAddStep,
  onDeleteStep
}) => {

  const addItem = (category: DeipCategory) => {
    const newItem: DeipItem = {
      id: generateId(),
      category,
      title: '',
      description: '',
      attention: false
    };
    onUpdateDeipItems([...(data.deipItems || []), newItem]);
    onSelect(newItem.id, 'deip');
  };

  const getItems = (category: DeipCategory) => {
    return (data.deipItems || []).filter(i => i.category === category);
  };

  const renderSection = (category: DeipCategory, title: string, icon: React.ReactNode, bgColor: string, borderColor: string) => {
      const items = getItems(category);
      return (
          <div className={cn("flex flex-col h-full border rounded-xl overflow-hidden shadow-sm bg-white", borderColor)}>
              <div className={cn("p-2 flex items-center justify-between border-b", bgColor, borderColor)}>
                  <div className="flex items-center gap-2 text-xs font-bold uppercase text-slate-700">
                      {icon} {title}
                  </div>
                  <Button 
                    size="icon" 
                    variant="ghost" 
                    className="w-5 h-5 hover:bg-white/50" 
                    onClick={() => addItem(category)}
                  >
                    <Plus size={14} />
                  </Button>
              </div>
              <div className="flex-1 p-2 overflow-y-auto custom-scrollbar bg-slate-50/30">
                  <div className="grid grid-cols-1 xl:grid-cols-2 gap-2">
                      {items.map(item => (
                          <DeipCard 
                            key={item.id} 
                            item={item} 
                            isSelected={selectedId === item.id}
                            onClick={() => onSelect(item.id, 'deip')}
                          />
                      ))}
                      {items.length === 0 && (
                          <div onClick={() => addItem(category)} className="border-2 border-dashed border-slate-200 rounded-lg p-4 flex flex-col items-center justify-center text-slate-400 cursor-pointer hover:border-slate-300 hover:bg-slate-50 transition-all min-h-[80px]">
                              <Plus size={16} className="mb-1" />
                              <span className="text-[10px] uppercase font-bold">Adicionar</span>
                          </div>
                      )}
                  </div>
              </div>
          </div>
      );
  };

  return (
    <div className="flex-1 overflow-auto custom-scrollbar p-6 bg-slate-100/50">
        <div className="min-w-[1000px] max-w-[1800px] mx-auto grid grid-cols-12 gap-4 auto-rows-min">

            {/* ROW 1: POLICIES (Top Center - Span 8 offset 2 for cleaner look, or full span) */}
            <div className="col-span-12 h-40">
                {renderSection(
                    'policies', 
                    'Políticas, Regras e Padrões', 
                    <Shield size={14} className="text-slate-600" />,
                    'bg-slate-100',
                    'border-slate-200'
                )}
            </div>

            {/* ROW 2: INPUTS - TIMELINE - OUTPUTS */}

            {/* Left: Inputs */}
            <div className="col-span-2 h-[260px]">
                {renderSection(
                    'inputs', 
                    'Entradas / Premissas', 
                    <ArrowRightFromLine size={14} className="text-green-600" />,
                    'bg-green-50',
                    'border-green-100'
                )}
            </div>

            {/* Center: Timeline */}
            <div className="col-span-8 h-[260px] flex items-center">
                <div className="w-full bg-white rounded-xl shadow-sm border border-slate-200 overflow-hidden">
                    <Timeline 
                        steps={data.steps}
                        selectedStepId={selectedId}
                        onSelectStep={(id) => onSelect(id, id === 'START' ? 'start' : id === 'END' ? 'end' : 'step')}
                        onUpdateSteps={onUpdateSteps}
                        onAddStep={onAddStep}
                        onDeleteStep={onDeleteStep}
                    />
                </div>
            </div>

            {/* Right: Outputs */}
            <div className="col-span-2 h-[260px]">
                {renderSection(
                    'outputs', 
                    'Saídas / Entregas', 
                    <ArrowLeftFromLine size={14} className="text-blue-600" />,
                    'bg-blue-50',
                    'border-blue-100'
                )}
            </div>

            {/* ROW 3: RESOURCES (Bottom Center) */}
            <div className="col-span-12 h-40">
                {renderSection(
                    'resources', 
                    'Suporte, Recursos e Ferramentas', 
                    <Hammer size={14} className="text-amber-600" />,
                    'bg-amber-50',
                    'border-amber-100'
                )}
            </div>

        </div>
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { ProcessHeader } from './components/ProcessHeader';
import { StepDetails } from './components/StepDetails';
import { NodeDetails } from './components/NodeDetails';
import { ProjectView } from './components/ProjectView';
import { ProcessSidebar } from './components/ProcessSidebar';
import { DeipLayout } from './components/DeipLayout';
import { DeipItemDetails } from './components/DeipItemDetails';
import { ProcessImprovement, ProcessStep, ProcessNode, DeipItem } from './types/process';
import { loadFromLocalStorage, saveToLocalStorage, validateProcessJson, getEmptyProcess, ensureCompatibleData } from './utils/exportUtils';
import { generateId, cn } from './lib/utils';
import { FileWarning, CheckCircle, LayoutTemplate, Rocket, X } from 'lucide-react';

type SelectedType = 'step' | 'deip' | 'start' | 'end' | null;

function App() {
  const [data, setData] = useState<ProcessImprovement | null>(null);

  // Selection State
  const [selectedId, setSelectedId] = useState<string | null>(null);
  const [selectedType, setSelectedType] = useState<SelectedType>(null);
  const [isPanelOpen, setIsPanelOpen] = useState(false);

  const [currentView, setCurrentView] = useState<'process' | 'project'>('process');
  const [notification, setNotification] = useState<{message: string, type: 'success' | 'error'} | null>(null);
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);

  useEffect(() => {
    const loadedData = loadFromLocalStorage();
    setData(loadedData);
    // Initial state: Panel closed, no selection
  }, []);

  useEffect(() => {
    if (data) {
      const timeoutId = setTimeout(() => {
        saveToLocalStorage({ ...data, updatedAt: new Date().toISOString() });
      }, 1000);
      return () => clearTimeout(timeoutId);
    }
  }, [data]);

  const showNotification = (message: string, type: 'success' | 'error') => {
    setNotification({ message, type });
    setTimeout(() => setNotification(null), 3000);
  };

  const handleUpdate = (field: keyof ProcessImprovement, value: any) => {
    if (!data) return;
    setData({ ...data, [field]: value });
  };

  const handleSelectElement = (id: string, type: SelectedType) => {
      setSelectedId(id);
      setSelectedType(type);
      setIsPanelOpen(true);
  };

  const handleClosePanel = () => {
      setIsPanelOpen(false);
      setSelectedId(null);
      setSelectedType(null);
  };

  const handleImport = (e: React.ChangeEvent<HTMLInputElement>) => {
      const file = e.target.files?.[0];
      if (file) {
          const reader = new FileReader();
          reader.onload = (event) => {
              try {
                  const importedData = JSON.parse(event.target?.result as string);
                  if (validateProcessJson(importedData)) {
                      setData(ensureCompatibleData(importedData));
                      handleClosePanel();
                      showNotification('Projeto carregado com sucesso!', 'success');
                  } else {
                      showNotification('Arquivo JSON inválido ou corrompido.', 'error');
                  }
              } catch (error) {
                  showNotification('Erro na leitura do arquivo.', 'error');
              }
          };
          reader.readAsText(file);
      }
      e.target.value = '';
  };

  // --- Handlers for Data Updates ---

  const updateSteps = (newSteps: ProcessStep[]) => {
      if (!data) return;
      setData({ ...data, steps: newSteps });
  };

  const handleAddStep = () => {
      if (!data) return;
      const newStep: ProcessStep = {
          id: generateId(),
          name: 'Nova Etapa',
          role: '',
          currentScenario: '',
          futureScenario: '',
          idealScenario: '',
          inputs: [],
          outputs: [],
          noImprovement: false,
          userCards: [],
          mappings: []
      };
      const newSteps = [...data.steps, newStep];
      setData({ ...data, steps: newSteps });
      handleSelectElement(newStep.id, 'step');
  };

  const handleDeleteStep = (id: string) => {
      if (!data) return;
      if(confirm("Tem certeza que deseja remover esta etapa?")) {
          const newSteps = data.steps.filter(s => s.id !== id);
          setData({ ...data, steps: newSteps });
          if (selectedId === id) handleClosePanel();
      }
  };

  const handleUpdateSelectedStep = (updatedStep: ProcessStep) => {
      if (!data) return;
      const newSteps = data.steps.map(s => s.id === updatedStep.id ? updatedStep : s);
      setData({ ...data, steps: newSteps });
  }

  const handleUpdateStartNode = (updatedNode: ProcessNode) => {
      if (!data) return;
      setData({ ...data, startNode: updatedNode });
  }

  const handleUpdateEndNode = (updatedNode: ProcessNode) => {
      if (!data) return;
      setData({ ...data, endNode: updatedNode });
  }

  const handleUpdateDeipItems = (items: DeipItem[]) => {
      if (!data) return;
      setData({ ...data, deipItems: items });
  }

  const handleUpdateDeipItem = (updatedItem: DeipItem) => {
      if (!data) return;
      const newItems = (data.deipItems || []).map(i => i.id === updatedItem.id ? updatedItem : i);
      setData({ ...data, deipItems: newItems });
  }

  const handleDeleteDeipItem = (id: string) => {
      if (!data) return;
      if(confirm("Excluir este item?")) {
          const newItems = (data.deipItems || []).filter(i => i.id !== id);
          setData({ ...data, deipItems: newItems });
          if (selectedId === id) handleClosePanel();
      }
  }

  if (!data) return null;

  // --- Render Logic for Bottom Panel Content ---
  let PanelContent = null;
  if (selectedType === 'start') {
      PanelContent = <NodeDetails node={data.startNode || { cards: [] }} type="start" onUpdate={handleUpdateStartNode} />;
  } else if (selectedType === 'end') {
      PanelContent = <NodeDetails node={data.endNode || { cards: [] }} type="end" onUpdate={handleUpdateEndNode} />;
  } else if (selectedType === 'step') {
      const selectedStep = data.steps.find(s => s.id === selectedId);
      if (selectedStep) {
          PanelContent = <StepDetails step={selectedStep} onUpdate={handleUpdateSelectedStep} />;
      }
  } else if (selectedType === 'deip') {
      const selectedItem = (data.deipItems || []).find(i => i.id === selectedId);
      if (selectedItem) {
          PanelContent = <DeipItemDetails item={selectedItem} onUpdate={handleUpdateDeipItem} onDelete={() => handleDeleteDeipItem(selectedItem.id)} />;
      }
  }

  if (!PanelContent) PanelContent = <div className="p-8 text-center text-slate-400">Item não encontrado.</div>;

  return (
    <div className="flex flex-col h-screen w-screen bg-[#f1f5f9] overflow-hidden">

      {/* Toast Notification */}
      {notification && (
        <div className={`fixed top-6 right-6 z-50 flex items-center gap-3 px-6 py-3 rounded-lg shadow-2xl animate-in slide-in-from-right-10 border ${
          notification.type === 'success' ? 'bg-white border-green-100 text-green-800' : 'bg-white border-red-100 text-red-800'
        }`}>
          {notification.type === 'success' ? <CheckCircle className="w-5 h-5 text-green-500" /> : <FileWarning className="w-5 h-5 text-red-500" />}
          <span className="font-semibold text-sm">{notification.message}</span>
        </div>
      )}

      {/* TOP NAV */}
      <div className="bg-slate-900 px-4 py-2 flex items-center justify-center border-b border-slate-800 shrink-0 z-50">
          <div className="bg-slate-800 p-1 rounded-lg flex items-center gap-1">
             <button 
                onClick={() => setCurrentView('process')}
                className={cn(
                    "px-4 py-1.5 rounded-md text-xs font-bold uppercase tracking-wide flex items-center gap-2 transition-all",
                    currentView === 'process' ? "bg-blue-600 text-white shadow" : "text-slate-400 hover:text-white hover:bg-slate-700"
                )}
             >
                <LayoutTemplate size={14} /> Mapeamento DEIP
             </button>
             <button 
                onClick={() => setCurrentView('project')}
                className={cn(
                    "px-4 py-1.5 rounded-md text-xs font-bold uppercase tracking-wide flex items-center gap-2 transition-all",
                    currentView === 'project' ? "bg-indigo-600 text-white shadow" : "text-slate-400 hover:text-white hover:bg-slate-700"
                )}
             >
                <Rocket size={14} /> Visão do Projeto
             </button>
          </div>
      </div>

      {currentView === 'process' ? (
        <div className="flex-1 flex overflow-hidden">
            {/* LEFT SIDEBAR (Collapsible) */}
            <ProcessSidebar 
                data={data}
                onUpdate={handleUpdate}
                isOpen={isSidebarOpen}
                onToggle={() => setIsSidebarOpen(!isSidebarOpen)}
            />

            {/* MAIN WORKSPACE */}
            <div className="flex-1 flex flex-col min-w-0 overflow-hidden relative">
                <ProcessHeader 
                    data={data} 
                    onUpdate={handleUpdate} 
                    onImport={handleImport}
                />

                {/* DEIP CANVAS (Timeline + Surroundings) */}
                <DeipLayout 
                    data={data}
                    selectedId={selectedId}
                    onSelect={handleSelectElement}
                    onUpdateDeipItems={handleUpdateDeipItems}
                    onUpdateSteps={updateSteps}
                    onAddStep={handleAddStep}
                    onDeleteStep={handleDeleteStep}
                />

                {/* COLLAPSIBLE BOTTOM PANEL */}
                <div className={cn(
                    "border-t border-slate-300 shadow-[0_-5px_15px_rgba(0,0,0,0.05)] bg-white transition-all duration-300 ease-in-out flex flex-col",
                    isPanelOpen ? "h-[450px]" : "h-0"
                )}>
                    {isPanelOpen && (
                        <div className="flex-1 flex flex-col min-h-0 relative">
                            {/* Close Button */}
                            <button 
                                onClick={handleClosePanel}
                                className="absolute top-2 right-4 z-20 p-1.5 bg-slate-100 hover:bg-slate-200 text-slate-500 rounded-full transition-colors"
                                title="Fechar Painel"
                            >
                                <X size={16} />
                            </button>

                            {/* Content */}
                            {PanelContent}
                        </div>
                    )}
                </div>
            </div>
        </div>
      ) : (
        <ProjectView data={data} onUpdate={handleUpdate} />
      )}

    </div>
  );
}

export default App;

