                                className="absolute top-2 right-4 z-20 p-1.5 bg-slate-100 hover:bg-slate-200 text-slate-500 rounded-full transition-colors"
                                title="Fechar Painel"
                            >
                                <X size={16} />
                            </button>

                            {/* Content */}
                            {PanelContent}
                        </div>
                    )}
                </div>
            </div>
        </div>
      ) : (
        <ProjectView data={data} onUpdate={handleUpdate} />
      )}

    </div>
  );
}

