            {/* Border around everything, rounded top */}
            <div className="col-span-12 h-44 z-10">
                {renderSection(
                    'policies', 
                    'Políticas, Regras e Padrões', 
                    <Shield size={14} className="text-slate-600" />,
                    'bg-slate-100',
                    'border border-slate-300 rounded-t-xl'
                )}
            </div>

            {/* ROW 2: INPUTS - TIMELINE - OUTPUTS */}

            {/* Left: Inputs */}
            {/* No top border (relies on policies bottom), no right border (relies on timeline left) */}
            <div className="col-span-2 h-[280px]">
                {renderSection(
