import { ProcessImprovement, ProcessStep, ProcessNode, DeipItem, ProcessFlow } from './types/process';
import { loadFromLocalStorage, saveToLocalStorage, validateProcessJson, getEmptyProcess, ensureCompatibleData } from './utils/exportUtils';
import { generateId, cn } from './lib/utils';
import { FileWarning, CheckCircle, LayoutTemplate, Rocket, X } from 'lucide-react';

type SelectedType = 'step' | 'deip' | 'start' | 'end' | null;

function App() {
  const [data, setData] = useState<ProcessImprovement | null>(null);
  const [activeFlowId, setActiveFlowId] = useState<string>('');

  // Selection State
  const [selectedId, setSelectedId] = useState<string | null>(null);
  const [selectedType, setSelectedType] = useState<SelectedType>(null);
  const [isPanelOpen, setIsPanelOpen] = useState(false);

  const [currentView, setCurrentView] = useState<'process' | 'project'>('process');
  const [notification, setNotification] = useState<{message: string, type: 'success' | 'error'} | null>(null);

  useEffect(() => {
    const loadedData = loadFromLocalStorage();
    setData(loadedData);
    if (loadedData.flows.length > 0) {
        setActiveFlowId(loadedData.flows[0].id);
    }
  }, []);

  useEffect(() => {
    if (data) {
      const timeoutId = setTimeout(() => {
        saveToLocalStorage({ ...data, updatedAt: new Date().toISOString() });
      }, 1000);
      return () => clearTimeout(timeoutId);
    }
  }, [data]);

  const showNotification = (message: string, type: 'success' | 'error') => {
    setNotification({ message, type });
    setTimeout(() => setNotification(null), 3000);
  };

  const handleUpdate = (field: keyof ProcessImprovement, value: any) => {
    if (!data) return;
    setData({ ...data, [field]: value });
  };

  const handleSelectElement = (id: string, type: SelectedType) => {
      setSelectedId(id);
      setSelectedType(type);
      setIsPanelOpen(true);
  };

  const handleClosePanel = () => {
      setIsPanelOpen(false);
      setSelectedId(null);
      setSelectedType(null);
  };

  const handleImport = (e: React.ChangeEvent<HTMLInputElement>) => {
      const file = e.target.files?.[0];
      if (file) {
          const reader = new FileReader();
          reader.onload = (event) => {
              try {
                  const importedData = JSON.parse(event.target?.result as string);
                  if (validateProcessJson(importedData)) {
                      const compatible = ensureCompatibleData(importedData);
                      setData(compatible);
                      if (compatible.flows.length > 0) {
                        setActiveFlowId(compatible.flows[0].id);
                      }
                      handleClosePanel();
                      showNotification('Projeto carregado com sucesso!', 'success');
                  } else {
                      showNotification('Arquivo JSON inválido ou corrompido.', 'error');
                  }
              } catch (error) {
                  showNotification('Erro na leitura do arquivo.', 'error');
              }
          };
          reader.readAsText(file);
      }
      e.target.value = '';
  };

  // --- Handlers for Flows ---

  const handleAddFlow = () => {
      if (!data) return;
      const newFlow: ProcessFlow = {
          id: generateId(),
          name: 'Novo Fluxo',
          steps: []
      };
      setData({ ...data, flows: [...data.flows, newFlow] });
      setActiveFlowId(newFlow.id);
  };

  const handleDeleteFlow = (flowId: string) => {
      if (!data) return;
      if (data.flows.length <= 1) {
          showNotification('É necessário ter pelo menos um fluxo.', 'error');
          return;
      }
      if (confirm('Tem certeza? Todas as etapas deste fluxo serão excluídas.')) {
          const newFlows = data.flows.filter(f => f.id !== flowId);
          setData({ ...data, flows: newFlows });
          if (activeFlowId === flowId) {
              setActiveFlowId(newFlows[0].id);
          }
      }
  };

  const handleUpdateFlowName = (flowId: string, name: string) => {
      if (!data) return;
      const newFlows = data.flows.map(f => f.id === flowId ? { ...f, name } : f);
      setData({ ...data, flows: newFlows });
  };

  // --- Handlers for Steps (Scoped to Flows) ---

  const updateSteps = (newSteps: ProcessStep[]) => {
      if (!data) return;
      const newFlows = data.flows.map(f => 
          f.id === activeFlowId ? { ...f, steps: newSteps } : f
      );
      setData({ ...data, flows: newFlows });
  };

  const handleAddStep = () => {
      if (!data || !activeFlowId) return;
      const newStep: ProcessStep = {
          id: generateId(),
          name: 'Nova Etapa',
          role: '',
          currentScenario: '',
          futureScenario: '',
          idealScenario: '',
          inputs: [],
          outputs: [],
          noImprovement: false,
          userCards: [],
          mappings: []
      };

      const newFlows = data.flows.map(f => {
          if (f.id === activeFlowId) {
              return { ...f, steps: [...f.steps, newStep] };
          }
          return f;
      });

      setData({ ...data, flows: newFlows });
      handleSelectElement(newStep.id, 'step');
  };

  const handleDeleteStep = (id: string) => {
      if (!data) return;
      if(confirm("Tem certeza que deseja remover esta etapa?")) {
          const newFlows = data.flows.map(f => ({
              ...f,
              steps: f.steps.filter(s => s.id !== id)
          }));
          setData({ ...data, flows: newFlows });
          if (selectedId === id) handleClosePanel();
      }
  };

  const handleUpdateSelectedStep = (updatedStep: ProcessStep) => {
      if (!data) return;
      // Precisamos encontrar em qual fluxo esta etapa está
      const newFlows = data.flows.map(f => ({
          ...f,
          steps: f.steps.map(s => s.id === updatedStep.id ? updatedStep : s)
      }));
      setData({ ...data, flows: newFlows });
  }

  // --- Helpers for other items ---

  const handleUpdateStartNode = (updatedNode: ProcessNode) => {
      if (!data) return;
      setData({ ...data, startNode: updatedNode });
  }

  const handleUpdateEndNode = (updatedNode: ProcessNode) => {
      if (!data) return;
      setData({ ...data, endNode: updatedNode });
  }

  const handleUpdateDeipItems = (items: DeipItem[]) => {
      if (!data) return;
      setData({ ...data, deipItems: items });
  }

  const handleUpdateDeipItem = (updatedItem: DeipItem) => {
      if (!data) return;
      const newItems = (data.deipItems || []).map(i => i.id === updatedItem.id ? updatedItem : i);
      setData({ ...data, deipItems: newItems });
  }

  const handleDeleteDeipItem = (id: string) => {
      if (!data) return;
      if(confirm("Excluir este item?")) {
          const newItems = (data.deipItems || []).filter(i => i.id !== id);
          setData({ ...data, deipItems: newItems });
          if (selectedId === id) handleClosePanel();
      }
  }

  // Helper to find step across all flows for the Details Panel
  const findStepById = (id: string): ProcessStep | undefined => {
      if (!data) return undefined;
      for (const flow of data.flows) {
          const step = flow.steps.find(s => s.id === id);
          if (step) return step;
      }
      return undefined;
  };

  if (!data) return null;

  // --- Render Logic for Bottom Panel Content ---
  let PanelContent = null;
  if (selectedType === 'start') {
      PanelContent = <NodeDetails node={data.startNode || { cards: [] }} type="start" onUpdate={handleUpdateStartNode} />;
  } else if (selectedType === 'end') {
      PanelContent = <NodeDetails node={data.endNode || { cards: [] }} type="end" onUpdate={handleUpdateEndNode} />;
  } else if (selectedType === 'step') {
      const selectedStep = findStepById(selectedId || '');
      if (selectedStep) {
          PanelContent = <StepDetails step={selectedStep} onUpdate={handleUpdateSelectedStep} />;
      }
  } else if (selectedType === 'deip') {
      const selectedItem = (data.deipItems || []).find(i => i.id === selectedId);
      if (selectedItem) {
          PanelContent = <DeipItemDetails item={selectedItem} onUpdate={handleUpdateDeipItem} onDelete={() => handleDeleteDeipItem(selectedItem.id)} />;
      }
  }

  if (!PanelContent) PanelContent = <div className="p-8 text-center text-slate-400">Item não encontrado.</div>;

  return (
    <div className="flex flex-col h-screen w-screen bg-[#f1f5f9] overflow-hidden">

      {/* Toast Notification */}
      {notification && (
        <div className={`fixed top-6 right-6 z-50 flex items-center gap-3 px-6 py-3 rounded-lg shadow-2xl animate-in slide-in-from-right-10 border ${
          notification.type === 'success' ? 'bg-white border-green-100 text-green-800' : 'bg-white border-red-100 text-red-800'
        }`}>
          {notification.type === 'success' ? <CheckCircle className="w-5 h-5 text-green-500" /> : <FileWarning className="w-5 h-5 text-red-500" />}
          <span className="font-semibold text-sm">{notification.message}</span>
        </div>
      )}

      {/* TOP NAV */}
      <div className="bg-slate-900 px-4 py-2 flex items-center justify-center border-b border-slate-800 shrink-0 z-50">
          <div className="bg-slate-800 p-1 rounded-lg flex items-center gap-1">
             <button 
                onClick={() => setCurrentView('process')}
                className={cn(
                    "px-4 py-1.5 rounded-md text-xs font-bold uppercase tracking-wide flex items-center gap-2 transition-all",
                    currentView === 'process' ? "bg-blue-600 text-white shadow" : "text-slate-400 hover:text-white hover:bg-slate-700"
                )}
             >
                <LayoutTemplate size={14} /> Mapeamento DEIP
             </button>
             <button 
                onClick={() => setCurrentView('project')}
                className={cn(
                    "px-4 py-1.5 rounded-md text-xs font-bold uppercase tracking-wide flex items-center gap-2 transition-all",
                    currentView === 'project' ? "bg-indigo-600 text-white shadow" : "text-slate-400 hover:text-white hover:bg-slate-700"
                )}
             >
                <Rocket size={14} /> Visão do Projeto
             </button>
          </div>
      </div>

      {currentView === 'process' ? (
        <div className="flex-1 flex overflow-hidden">
            {/* MAIN WORKSPACE - No Sidebar */}
            <div className="flex-1 flex flex-col min-w-0 overflow-hidden relative">
                <ProcessHeader 
                    data={data} 
                    onUpdate={handleUpdate} 
                    onImport={handleImport}
                />

                {/* DEIP CANVAS (Timeline + Surroundings) */}
                <DeipLayout 
                    data={data}
                    activeFlowId={activeFlowId}
                    setActiveFlowId={setActiveFlowId}
                    selectedId={selectedId}
                    onSelect={handleSelectElement}
                    onUpdateDeipItems={handleUpdateDeipItems}
                    onDeleteDeipItem={handleDeleteDeipItem}
                    onUpdateSteps={updateSteps}
                    onAddStep={handleAddStep}
                    onDeleteStep={handleDeleteStep}
                    onAddFlow={handleAddFlow}
                    onDeleteFlow={handleDeleteFlow}
                    onUpdateFlowName={handleUpdateFlowName}
                />

                {/* COLLAPSIBLE BOTTOM PANEL */}
                <div className={cn(
                    "border-t border-slate-300 shadow-[0_-5px_15px_rgba(0,0,0,0.05)] bg-white transition-all duration-300 ease-in-out flex flex-col z-30 relative",
                    isPanelOpen ? "h-[450px]" : "h-0"
                )}>
                    {isPanelOpen && (
                        <div className="flex-1 flex flex-col min-h-0 relative">
                            {/* Close Button */}
                            <button 
                                onClick={handleClosePanel}
                                className="absolute top-2 right-4 z-20 p-1.5 bg-slate-100 hover:bg-slate-200 text-slate-500 rounded-full transition-colors"
                                title="Fechar Painel"
                            >
                                <X size={16} />
                            </button>

                            {/* Content */}
                            {PanelContent}
                        </div>
                    )}
                </div>
            </div>
        </div>
      ) : (
        <ProjectView data={data} onUpdate={handleUpdate} />
      )}

    </div>
  );
}

export default App;

import React from 'react';
import { ProcessImprovement, DeipItem, DeipCategory } from '../types/process';
import { Timeline } from './Timeline';
import { DeipCard } from './DeipCard';
import { Plus, Shield, ArrowRightToLine, ArrowRightFromLine, Hammer, Layers, Trash2 } from 'lucide-react';
import { generateId, cn } from '../lib/utils';
import { Button } from './ui/button';
import { EditableText } from './EditableText';

interface DeipLayoutProps {
  data: ProcessImprovement;
  selectedId: string | null;
  activeFlowId: string;
  setActiveFlowId: (id: string) => void;
  onSelect: (id: string, type: 'step' | 'deip' | 'start' | 'end') => void;
  onUpdateDeipItems: (items: DeipItem[]) => void;
  onDeleteDeipItem: (id: string) => void;

  // Timeline props
  onUpdateSteps: (steps: any[]) => void;
  onAddStep: () => void;
  onDeleteStep: (id: string) => void;

  // Flow props
  onAddFlow: () => void;
  onDeleteFlow: (id: string) => void;
  onUpdateFlowName: (id: string, name: string) => void;
}

export const DeipLayout: React.FC<DeipLayoutProps> = ({
  data,
  selectedId,
  activeFlowId,
  setActiveFlowId,
  onSelect,
  onUpdateDeipItems,
  onDeleteDeipItem,
  onUpdateSteps,
  onAddStep,
  onDeleteStep,
  onAddFlow,
  onDeleteFlow,
  onUpdateFlowName
}) => {

  const addItem = (category: DeipCategory) => {
    const newItem: DeipItem = {
      id: generateId(),
      category,
      title: '',
      description: '',
      attention: false
    };
    onUpdateDeipItems([...(data.deipItems || []), newItem]);
    onSelect(newItem.id, 'deip');
  };

  const getItems = (category: DeipCategory) => {
    return (data.deipItems || []).filter(i => i.category === category);
  };

  const activeFlow = data.flows.find(f => f.id === activeFlowId) || data.flows[0];

  const renderSection = (
      category: DeipCategory, 
      title: string, 
      icon: React.ReactNode, 
      bgColor: string, 
      className: string,
      gridClasses: string
    ) => {
      const items = getItems(category);
      return (
          <div className={cn("flex flex-col h-full overflow-hidden bg-white", className)}>
              <div className={cn("px-2 py-1.5 flex items-center justify-between border-b border-slate-200 h-8", bgColor)}>
                  <div className="flex items-center gap-1.5 text-[10px] font-bold uppercase text-slate-700 whitespace-nowrap overflow-hidden">
                      <div className="shrink-0">{icon}</div>
                      <span className="truncate" title={title}>{title}</span>
                  </div>
                  <Button 
                    size="icon" 
                    variant="ghost" 
                    className="w-5 h-5 hover:bg-white/50 shrink-0 ml-1" 
                    onClick={() => addItem(category)}
                  >
                    <Plus size={14} />
                  </Button>
              </div>
              <div className="flex-1 p-2 overflow-y-auto custom-scrollbar bg-white">
                  <div className={cn("grid gap-2", gridClasses)}>
                      {items.map(item => (
                          <DeipCard 
                            key={item.id} 
                            item={item} 
                            isSelected={selectedId === item.id}
                            onClick={() => onSelect(item.id, 'deip')}
                            onDelete={() => onDeleteDeipItem(item.id)}
                          />
                      ))}
                      {items.length === 0 && (
                          <div onClick={() => addItem(category)} className="border-2 border-dashed border-slate-100 rounded-lg p-4 flex flex-col items-center justify-center text-slate-300 cursor-pointer hover:border-slate-300 hover:bg-slate-50 transition-all min-h-[80px]">
                              <Plus size={16} className="mb-1" />
                              <span className="text-[9px] uppercase font-bold">Adicionar</span>
                          </div>
                      )}
                  </div>
              </div>
          </div>
      );
  };

  return (
    <div className="flex-1 overflow-auto custom-scrollbar p-8 bg-slate-100">
        <div className="min-w-[1000px] max-w-[1800px] mx-auto grid grid-cols-12 gap-0 auto-rows-min shadow-sm">

            {/* ROW 1: POLICIES (Top Center) */}
            <div className="col-span-12 h-44 z-10">
                {renderSection(
                    'policies', 
                    'Políticas, Regras e Padrões', 
                    <Shield size={14} className="text-slate-600" />,
                    'bg-slate-100',
                    'border border-slate-300 rounded-t-xl',
                    'grid-cols-2 md:grid-cols-4 lg:grid-cols-5 xl:grid-cols-6'
                )}
            </div>

            {/* ROW 2: INPUTS - FLOWS/TIMELINE - OUTPUTS */}

            {/* Left: Inputs */}
            <div className="col-span-2 h-[280px]">
                {renderSection(
                    'inputs', 
                    'Entradas / Premissas', 
                    <ArrowRightToLine size={14} className="text-green-600" />,
                    'bg-green-50',
                    'border-l border-b border-slate-300',
                    'grid-cols-1 xl:grid-cols-2'
                )}
            </div>

            {/* Center: Flows + Timeline */}
            <div className="col-span-8 h-[280px] flex bg-white border-l border-b border-slate-300 overflow-hidden relative">

                 {/* Sidebar: Fluxos */}
                 <div className="w-48 border-r border-slate-200 bg-slate-50 flex flex-col min-w-0">
                    <div className="h-8 flex items-center justify-between px-2 bg-slate-100 border-b border-slate-200">
                        <div className="flex items-center gap-1.5 text-[10px] font-bold uppercase text-slate-600">
                            <Layers size={12} />
                            Fluxos
                        </div>
                        <Button 
                            size="icon" 
                            variant="ghost" 
                            className="w-5 h-5 hover:bg-white text-slate-500" 
                            onClick={onAddFlow}
                            title="Adicionar Novo Fluxo"
                        >
                            <Plus size={12} />
                        </Button>
                    </div>
                    <div className="flex-1 overflow-y-auto custom-scrollbar p-1 space-y-1">
                        {data.flows.map(flow => (
                            <div 
                                key={flow.id}
                                onClick={() => setActiveFlowId(flow.id)}
                                className={cn(
                                    "px-2 py-2 rounded text-xs cursor-pointer flex items-center group relative border",
                                    activeFlowId === flow.id 
                                        ? "bg-white border-slate-300 shadow-sm font-semibold text-slate-800" 
                                        : "border-transparent hover:bg-slate-200/50 text-slate-600"
                                )}
                            >
                                <div className="flex-1 min-w-0 pr-4">
                                     <EditableText 
                                        value={flow.name}
                                        onChange={(val) => onUpdateFlowName(flow.id, val)}
                                        className={cn("w-full truncate bg-transparent", activeFlowId !== flow.id && "pointer-events-none")}
                                     />
                                </div>
                                {data.flows.length > 1 && (
                                    <button
                                        onClick={(e) => { e.stopPropagation(); onDeleteFlow(flow.id); }}
                                        className="opacity-0 group-hover:opacity-100 absolute right-1 top-1/2 -translate-y-1/2 p-1 text-slate-400 hover:text-red-500"
                                    >
                                        <Trash2 size={10} />
                                    </button>
                                )}
                            </div>
                        ))}
                    </div>
                 </div>

                 {/* Main Area: Timeline */}
                 <div className="flex-1 min-w-0 h-full">
                     <Timeline 
                        steps={activeFlow ? activeFlow.steps : []}
                        selectedStepId={selectedId}
                        onSelectStep={(id) => onSelect(id, id === 'START' ? 'start' : id === 'END' ? 'end' : 'step')}
                        onUpdateSteps={onUpdateSteps}
                        onAddStep={onAddStep}
                        onDeleteStep={onDeleteStep}
                        className="h-full border-none rounded-none shadow-none w-full"
                     />
                 </div>
            </div>

            {/* Right: Outputs */}
            <div className="col-span-2 h-[280px]">
                {renderSection(
                    'outputs', 
                    'Saídas / Entregas', 
                    <ArrowRightFromLine size={14} className="text-blue-600" />,
                    'bg-blue-50',
                    'border-l border-b border-r border-slate-300',
                    'grid-cols-1 xl:grid-cols-2'
                )}
            </div>

            {/* ROW 3: RESOURCES (Bottom Center) */}
            <div className="col-span-12 h-44">
                {renderSection(
                    'resources', 
                    'Suporte, Recursos e Ferramentas', 
                    <Hammer size={14} className="text-amber-600" />,
                    'bg-amber-50',
                    'border-l border-b border-r border-slate-300 rounded-b-xl',
                    'grid-cols-2 md:grid-cols-4 lg:grid-cols-5 xl:grid-cols-6'
                )}
            </div>

        </div>
    </div>
  );
};

import React from 'react';
import { ProcessImprovement, DeipItem, DeipCategory } from '../types/process';
import { Timeline } from './Timeline';
import { DeipCard } from './DeipCard';
import { Plus, Shield, ArrowRightToLine, ArrowRightFromLine, Hammer, Layers, Trash2 } from 'lucide-react';
import { generateId, cn } from '../lib/utils';
import { Button } from './ui/button';
import { EditableText } from './EditableText';

interface DeipLayoutProps {
  data: ProcessImprovement;
  selectedId: string | null;
  activeFlowId: string;
  setActiveFlowId: (id: string) => void;
  onSelect: (id: string, type: 'step' | 'deip' | 'start' | 'end') => void;
  onUpdateDeipItems: (items: DeipItem[]) => void;
  onDeleteDeipItem: (id: string) => void;

  // Timeline props
  onUpdateSteps: (steps: any[]) => void;
  onAddStep: () => void;
  onDeleteStep: (id: string) => void;

  // Flow props
  onAddFlow: () => void;
  onDeleteFlow: (id: string) => void;
  onUpdateFlowName: (id: string, name: string) => void;
}

export const DeipLayout: React.FC<DeipLayoutProps> = ({
  data,
  selectedId,
  activeFlowId,
  setActiveFlowId,
  onSelect,
  onUpdateDeipItems,
  onDeleteDeipItem,
  onUpdateSteps,
  onAddStep,
  onDeleteStep,
  onAddFlow,
  onDeleteFlow,
  onUpdateFlowName
}) => {

  const addItem = (category: DeipCategory) => {
    const newItem: DeipItem = {
      id: generateId(),
      category,
      title: '',
      description: '',
      attention: false
    };
    onUpdateDeipItems([...(data.deipItems || []), newItem]);
    onSelect(newItem.id, 'deip');
  };

  const getItems = (category: DeipCategory) => {
    return (data.deipItems || []).filter(i => i.category === category);
  };

  const activeFlow = data.flows.find(f => f.id === activeFlowId) || data.flows[0];

  const renderSection = (
      category: DeipCategory, 
      title: string, 
      icon: React.ReactNode, 
      bgColor: string, 
      className: string,
      gridClasses: string
    ) => {
      const items = getItems(category);
      return (
          <div className={cn("flex flex-col h-full overflow-hidden bg-white", className)}>
              <div className={cn("px-2 py-1.5 flex items-center justify-between border-b border-slate-200 h-8", bgColor)}>
                  <div className="flex items-center gap-1.5 text-[10px] font-bold uppercase text-slate-700 whitespace-nowrap overflow-hidden">
                      <div className="shrink-0">{icon}</div>
                      <span className="truncate" title={title}>{title}</span>
                  </div>
                  <Button 
                    size="icon" 
                    variant="ghost" 
                    className="w-5 h-5 hover:bg-white/50 shrink-0 ml-1" 
                    onClick={() => addItem(category)}
                  >
                    <Plus size={14} />
                  </Button>
              </div>
              <div className="flex-1 p-2 overflow-y-auto custom-scrollbar bg-white">
                  <div className={cn("grid gap-2", gridClasses)}>
                      {items.map(item => (
                          <DeipCard 
                            key={item.id} 
                            item={item} 
                            isSelected={selectedId === item.id}
                            onClick={() => onSelect(item.id, 'deip')}
                            onDelete={() => onDeleteDeipItem(item.id)}
                          />
                      ))}
                      {items.length === 0 && (
                          <div onClick={() => addItem(category)} className="border-2 border-dashed border-slate-100 rounded-lg p-4 flex flex-col items-center justify-center text-slate-300 cursor-pointer hover:border-slate-300 hover:bg-slate-50 transition-all min-h-[80px]">
                              <Plus size={16} className="mb-1" />
                              <span className="text-[9px] uppercase font-bold">Adicionar</span>
                          </div>
                      )}
                  </div>
              </div>
          </div>
      );
  };

  return (
    <div className="flex-1 overflow-auto custom-scrollbar p-8 bg-slate-100">
        <div className="min-w-[1000px] max-w-[1800px] mx-auto grid grid-cols-12 gap-0 auto-rows-min shadow-sm">

            {/* ROW 1: POLICIES (Top Center) */}
